INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4711', 'spa', 'Canasta o espuerta grande; usada para transportar alimentos o descender a una persona, distinta del más pequeño κόφινος.', 'Canasta grande de mimbre, claramente diferenciada en los Evangelios del más pequeño κόφινος (G2894). Cuando Jesús alimentó a los cuatro mil, las sobras llenaron siete espuertas grandes (Mt 15:37; Mc 8:8), y luego Jesús recuerda este detalle a sus discípulos (Mt 16:10; Mc 8:20). La misma palabra describe la canasta empleada para descender a Pablo por la muralla de Damasco (Hch 9:25), indicando un recipiente lo suficientemente grande como para contener a un hombre adulto. Las cinco apariciones neotestamentarias se agrupan en torno a estos dos episodios, confirmando un único sentido concreto referido a un cesto de gran tamaño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4712', 'spa', 'Estadio: unidad de distancia (~185 m / 607 pies), o el recinto deportivo donde se celebraban competencias atléticas.', 'Στάδιον deriva del verbo ἵστημι (''estar de pie, fijar'') y originalmente designaba una medida fija de longitud, aproximadamente 185 metros. En los Evangelios y Apocalipsis aparece como marcador directo de distancia: los discípulos reman veinticinco o treinta estadios por el mar (Juan 6:19) y Emaús se encuentra a sesenta estadios de Jerusalén (Lucas 24:13). Sin embargo, en 1 Corintios 9:24 Pablo emplea el sentido arquitectónico concreto de la palabra: la pista o arena donde los corredores compiten por un premio. El contexto de cada pasaje desambigua entre la medida de distancia y el recinto deportivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4714', 'spa', 'Posición fija o establecida; por extensión, disputa facciosa, disensión o insurrección violenta contra la autoridad.', 'Derivado del verbo ἵστημι («estar de pie»), στάσις posee el sentido concreto de posición establecida, como en Hebreos 9:8 donde el primer tabernáculo aún «tiene vigencia». Sin embargo, en el Nuevo Testamento predomina el sentido de conflicto: disputas acaloradas dentro de comunidades religiosas (Hch 15:2; 23:7) e insurrecciones violentas contra el orden civil, como cuando Barrabás es encarcelado por la insurrección en Jerusalén (Lc 23:19, 25). El español distingue bien estos matices: «disensión» para el desacuerdo interno frente a «insurrección» para la revuelta armada, revelando cuán estrecha era la línea entre debate y levantamiento en el mundo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4716', 'spa', 'cruz — instrumento de madera de la crucifixión romana y, por extensión, la muerte expiatoria de Cristo', 'cruz — instrumento de madera de la crucifixión romana y, por extensión, la muerte expiatoria de Cristo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4717', 'spa', 'Crucificar — ejecutar fijando en una cruz; figuradamente, dar muerte al poder del pecado', 'Crucificar — ejecutar fijando en una cruz; figuradamente, dar muerte al poder del pecado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4718', 'spa', 'racimo o manojo de uvas; fruto fresco aun en la vid o recien cosechado', 'La palabra griega para un racimo de uvas, frutos agrupados en el tallo. Jesus la emplea en ensenanzas paralelas: no se cosechan uvas de los espinos (Mt 7:16, Lc 6:44), y Apocalipsis 14:18 describe a un angel recogiendo ''los racimos de la vid de la tierra'' para el lagar de la ira de Dios. La imagen evoca vinedos, cosecha y el fruto que revela la verdadera naturaleza de la planta. El griego clasico distingue la uva fresca (σταφυλή) de la pasa y la uva verde, enfatizando el estado maduro y listo para la vendimia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4719', 'spa', 'Espiga; la parte superior del tallo de un cereal que contiene los granos, especialmente de trigo o cebada.', 'La espiga es la cabeza o punta del tallo de un cereal, la parte que contiene los granos comestibles. Las cinco apariciones en el NT se relacionan con campos de cultivo e imágenes agrícolas. En la controversia del sábado, los discípulos arrancan espigas mientras caminan por los sembrados (Mt 12:1; Mc 2:23; Lc 6:1). Marcos 4:28 emplea el término dos veces en la parábola de la semilla que crece, trazando el desarrollo de la planta desde el brote verde hasta la espiga formada y luego el grano maduro. La palabra evoca el mundo agrario de la Palestina del siglo primero, donde la mies en sazón era parte del paisaje cotidiano y fuente rica de metáforas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4721', 'spa', 'Techo; cubierta superior de un edificio que ofrece protección y resguardo', 'Término griego que designa el techo, la cubierta superior de una casa o edificio. En el NT aparece en declaraciones sobre indignidad: el centurión se declara indigno de que Jesús entre «bajo su techo» (Mt 8:8, Lc 7:6), y unos amigos descuelgan a un paralítico a través del techo para acercarlo a Jesús (Mc 2:4). El techo representa el límite y la protección del hogar; entrar bajo el techo de alguien significa entrar en su espacio doméstico y aceptar su hospitalidad. En el griego clásico abarca tanto la estructura del tejado como, por extensión, la casa o morada que cubre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4722', 'spa', 'Soportar, aguantar, sobrellevar con paciencia; cubrir o contener sin ceder', 'Derivado de la raíz στέγη (''techo, cubierta''), este verbo significaba originalmente impedir que el agua pase — ser impermeable. Esa imagen concreta de cubrir y contener se desarrolló en una poderosa metáfora de resistencia paciente. Pablo lo usa para describir su disposición a «soportar cualquier cosa» antes que obstaculizar el evangelio (1 Corintios 9:12). En el gran himno al amor de 1 Corintios 13:7, el amor «todo lo soporta» — στέγει πάντα — cubriendo faltas y absorbiendo adversidades. En 1 Tesalonicenses 3:1 y 3:5, Pablo dice que «ya no podía soportarlo más», revelando la intensidad emocional del verbo: un recipiente que finalmente se desborda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4723', 'spa', 'Estéril, infecunda; dicho de una mujer incapaz de concebir, a menudo contrastada con el poder vivificador de Dios.', 'Adjetivo que significa ''estéril'' o ''infecunda'', aplicado exclusivamente a mujeres en el Nuevo Testamento. Aparece en relatos de inversión milagrosa: Elisabet, siendo estéril y de edad avanzada, concibe a Juan el Bautista (Lc 1:7, 36). Jesús pronuncia una bendición paradójica sobre las estériles ante la tribulación venidera (Lc 23:29). Pablo cita Isaías 54:1 en Gálatas 4:27, donde la mujer estéril que se regocija prefigura la fecundidad del nuevo pacto. Hebreos 11:11 celebra que Sara recibió fuerza para concebir a pesar de haber pasado ya la edad. En cada caso, la esterilidad humana se convierte en escenario para la intervención divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4727', 'spa', 'στενάζω — gemir, suspirar profundamente o lamentarse bajo el peso del sufrimiento o el anhelo', 'Forma frecuentativa de στένω (''gemir''), στενάζω expresa un suspiro o gemido profundo y visceral bajo una carga emocional o física. En Marcos 7:34, Jesús mismo suspira profundamente (στενάξας) antes de sanar al sordo, una rara visión de la compasión encarnada del Señor. Pablo usa el término para describir a los creyentes que gimen interiormente mientras aguardan la redención de sus cuerpos (Rom 8:23) y anhelan ser revestidos de su morada celestial (2 Cor 5:2, 4). Hebreos 13:17 advierte contra hacer gemir a los líderes por desobediencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4728', 'spa', 'Estrecho, angosto, reducido; que carece de amplitud o anchura, opuesto a ancho o espacioso', 'Adjetivo que significa estrecho, angosto, ceñido, lo opuesto a ancho o amplio. Jesús lo emplea en su enseñanza sobre los dos caminos: la puerta es estrecha y el camino es difícil que conduce a la vida (Mt 7:13-14, Lc 13:24). La puerta estrecha exige esfuerzo para entrar; no da cabida a multitudes ni a cargas superfluas. En el griego clásico se usa para pasos montañosos angostos, estrechos entre mares o espacios reducidos donde el movimiento es limitado. En la metáfora de Jesús, el camino estrecho demanda entrega, disciplina y devoción singular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4729', 'spa', 'Estar constreñido, apretado o angustiado; experimentar restricción o aflicción', 'Verbo que significa estar apretado, confinado o bajo presión, ya sea en sentido espacial (estar hacinado) o emocional y espiritual (estar angustiado). Pablo lo usa tres veces en 2 Corintios: «atribulados en todo, pero no aplastados» (4:8), y dos veces en 6:12 explicando que los corintios no están limitados por el afecto de Pablo, sino «constreñidos en sus propios afectos». El término transmite tanto la presión externa (estar acorralado) como la constricción interna (estrechez emocional o dureza de corazón). En el uso clásico incluye hacinamiento físico, estrecheces médicas y restricción metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4730', 'spa', 'Angustia, aflicción extrema, aprieto — una estrechez de circunstancias que oprime por todos lados', 'Literalmente ''estrechez de espacio'' (de στενός, ''estrecho'', y χώρα, ''espacio''), este sustantivo retrata vívidamente la sensación de estar acorralado sin posibilidad de movimiento. Pablo lo empareja frecuentemente con θλῖψις (''tribulación'') formando una hendíadis de presión total: aflicción externa y angustia interna juntas. En Romanos 2:9 aguarda a toda alma que obra el mal; en Romanos 8:35 aparece en el catálogo de fuerzas que no pueden separar a los creyentes del amor de Cristo. Los catálogos de sufrimientos en 2 Corintios 6:4 y 12:10 lo incluyen entre las penalidades del apóstol. El español ''angustia'' preserva bien el sentido de opresión aplastante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4731', 'spa', 'Firme, sólido, duro; en sentido figurado, constante e inquebrantable en la fe o convicción', 'Este adjetivo describe lo que es físicamente duro e inflexible: piedra sólida frente a espacio vacío, hueso firme frente a tejido blando. El Nuevo Testamento traslada esta concreción al ámbito espiritual. Hebreos 5:12-14 contrasta el «alimento sólido» con la leche, usando στερεός para describir la enseñanza madura destinada a los espiritualmente desarrollados. Pablo declara que el «fundamento firme» de Dios permanece inconmovible (2 Tim 2:19), y Pedro exhorta a los creyentes a resistir al diablo «firmes en la fe» (1 Pe 5:9). En cada caso, la imagen física de solidez —algo contra lo que se presiona y no cede— ancla la metáfora de una resolución espiritual inquebrantable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4732', 'spa', 'Fortalecer, hacer firme o sólido; establecer con seguridad, dar estabilidad y vigor', 'Verbo que significa hacer fuerte, firme o sólido: fortalecer y establecer. En Hechos aparece dos veces en la sanación del cojo: sus pies y tobillos «fueron fortalecidos» (3:7), y fue la fe la que lo «fortaleció» (3:16). Hechos 16:5 informa que las iglesias «eran fortalecidas» en la fe cada día. El término abarca tanto la restauración física (miembros débiles hechos fuertes) como la fortificación espiritual (fe establecida y confirmada). En el uso clásico incluye solidificar estructuras, afianzar cimientos y confirmar decisiones o juicios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4734', 'spa', 'Estéfanas; nombre propio, primer convertido en Acaya cuya casa fue bautizada por Pablo', 'Nombre propio que aparece tres veces en 1 Corintios. Pablo menciona haber bautizado a la familia de Estéfanas (1:16), los describe como «las primicias de Acaya» dedicados al servicio de los santos (16:15), y se regocija por la llegada de Estéfanas junto con Fortunato y Acaico (16:17). Esta familia representa el éxito temprano de Pablo en Corinto y es modelo de liderazgo servicial. El nombre (relacionado con ''corona'') era común en la sociedad griega. Estéfanas y su familia ejemplifican el tipo de creyentes estables y comprometidos que Pablo anhelaba en Corinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4735', 'spa', 'Corona, guirnalda — un circulo tejido de honor, victoria o dignidad real; la guirnalda del vencedor y la recompensa del martir. στέφανος designa una g', 'Corona, guirnalda — un circulo tejido de honor, victoria o dignidad real; la guirnalda del vencedor y la recompensa del martir. στέφανος designa una guirnalda o corona tejida de hojas, flores o materiales preciosos, colocada sobre la cabeza para significar honor, victoria o autoridad. A diferencia de διάδημα (la diadema real del poder soberano), στέφανος es la guirnalda del vencedor, la corona ganada mediante contienda, perseverancia o fidelidad. Sus 18 apariciones en el Nuevo Testamento se dividen en dos categorias: la corona de espinas como parodia cruel de la realeza (Mt 27:29; Mc 15:17; Jn 19:2, 5), y la corona metaforica de recompensa, como la ''corona incorruptible'' del atleta disciplinado (1 Co 9:25) y ''la corona de justicia'' (2 Ti 4:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4736', 'spa', 'Esteban: primer mártir cristiano, uno de los siete diáconos, conocido por su testimonio lleno del Espíritu y su muerte por lapidación.', 'Στέφανος (que significa ''corona'' o ''guirnalda'' en griego) es el nombre propio del primer mártir cristiano registrado. Elegido como uno de siete hombres ''llenos del Espíritu y de sabiduría'' para servir a la iglesia primitiva de Jerusalén (Hechos 6:5), Esteban realizaba señales y prodigios y participaba en debates públicos poderosos (Hechos 6:8-10). Su extenso discurso ante el Sanedrín (Hechos 7) repasó la historia de Israel rechazando a los mensajeros de Dios, lo cual desembocó en su lapidación mientras oraba por sus verdugos (Hechos 7:59-60). Su muerte, presenciada por Saulo de Tarso (Hechos 8:1; 22:20), fue catalizador de la expansión de la iglesia más allá de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4737', 'spa', 'Coronar, ceñir con guirnalda o corona; honrar colocando una corona o laurel de victoria sobre alguien', 'Verbo que significa coronar o ceñir con una corona, guirnalda o laurel, generalmente como señal de honor o recompensa. Aparece en 2 Timoteo 2:5, donde el atleta solo es coronado si compite conforme a las reglas, y dos veces en Hebreos 2:7, 9 citando el Salmo 8 sobre la humanidad coronada de gloria y honra, aplicado a Jesús. Los usos del NT entrelazan la recompensa atlética, el honor real y la exaltación mesiánica, donde ser coronado implica tanto mérito como gracia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4738', 'spa', 'Pecho, torso; la parte frontal del cuerpo, asociada con la cercanía afectiva, el duelo y el atuendo sacerdotal.', 'El pecho o torso, es decir, la parte frontal del cuerpo superior, que aparece en el Nuevo Testamento en contextos de expresión emocional, cercanía íntima y vestimenta ceremonial. El publicano se golpea el pecho en humilde arrepentimiento (Lc 18:13), y las multitudes regresan del Calvario golpeándose el pecho de dolor (Lc 23:48). El discípulo amado se recuesta sobre el pecho de Jesús en la Última Cena (Jn 13:25; 21:20), en una postura de profunda intimidad y confianza. En Apocalipsis 15:6, los ángeles aparecen ceñidos con bandas de oro sobre el pecho, evocando esplendor sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4739', 'spa', 'Mantenerse firme o perseverar en la fe y el compromiso; también estar de pie físicamente, estar en posición erguida. Στήκω (stēkō) es un presente tard', 'Mantenerse firme o perseverar en la fe y el compromiso; también estar de pie físicamente, estar en posición erguida. Στήκω (stēkō) es un presente tardío del griego koiné formado a partir de ἕστηκα, el perfecto de ἵστημι (''estar de pie''), y traslada la fuerza estable y asentada de ese tema perfectivo a un verbo nuevo. Pablo lo hizo suyo: ''Estad firmes en el Señor'' (Fil 4:1), ''Estad firmes y retened las tradiciones'' (2 Ts 2:15), ''Para libertad Cristo nos hizo libres; estad firmes'' (Gá 5:1). El español ''estad firmes'' y ''estáis firmes'' traducen consistentemente este sentido resuelto y exhortativo. Sin embargo, en Marcos la palabra conserva su sentido más simple de estar de pie físicamente: la madre y los hermanos de Jesús ''de pie'' afuera (Mr 3:31), y ''cuando estéis de pie orando, perdonad'' (Mr 11:25). La postura física y la postura espiritual se encuentran en este único verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4741', 'spa', 'Una palabra de profundo peso pastoral en el Nuevo Testamento, usada cuando Jesús ora para que la fe de Pedro no desfallezca y le encarga ''confirma a t', 'Una palabra de profundo peso pastoral en el Nuevo Testamento, usada cuando Jesús ora para que la fe de Pedro no desfallezca y le encarga ''confirma a tus hermanos'' (Lucas 22:32), o cuando Pablo ora para que Dios ''afirme vuestros corazones irreprensibles'' (1 Tesalonicenses 3:13). La imagen subyacente es la de apuntalar algo para que se mantenga firme, visible en el sentido literal de Jesús ''afirmando su rostro'' resueltamente hacia Jerusalén (Lucas 9:51) y el ''gran abismo fijado'' entre el lado de Abraham y el Hades (Lucas 16:26).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4745', 'spa', 'Pórtico con columnas, columnata techada o pasadizo cubierto en la arquitectura de templos y ciudades antiguas', 'Una stoa era un pasadizo cubierto con hileras de columnas, una de las estructuras más representativas de la arquitectura pública grecorromana. La más célebre fue la Stoa Poikilé («Pórtico Pintado») de Atenas, donde Zenón enseñó y dio nombre a la escuela estoica. En el Nuevo Testamento, el Pórtico de Salomón, situado en el costado oriental del templo de Jerusalén, es el escenario recurrente. Cobijaba el estanque de Betesda con sus cinco pórticos (Jn 5:2) y fue el lugar donde Jesús caminó durante la Fiesta de la Dedicación (Jn 10:23). La iglesia primitiva se congregaba allí (Hch 3:11; 5:12), convirtiendo este elemento arquitectónico en escenario de algunos de los momentos públicos más dramáticos del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4747', 'spa', 'Elementos: componentes básicos del mundo, ya sea sustancias físicas, principios rudimentarios de enseñanza o poderes espirituales cósmicos.', 'Στοιχεῖον significaba originalmente la sombra en un reloj solar que marcaba la hora, y luego pasó a designar cualquier unidad básica de una serie: una letra del alfabeto, un elemento de la materia o un principio fundamental del conocimiento. En el Nuevo Testamento adquiere peso teológico en dos direcciones distintas. Pablo advierte contra volver a ''los elementos del mundo'' (Gálatas 4:3, 9; Colosenses 2:8, 20), refiriéndose probablemente a los principios reguladores básicos — ya sean observancias de la Torá o fuerzas cósmicas paganas — que antes mantenían en esclavitud a los creyentes. El autor de Hebreos lo usa de otro modo, reprochando a los lectores que necesitan que alguien les enseñe de nuevo ''los elementos'' (el abecé) de los oráculos de Dios (Hebreos 5:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4748', 'spa', 'Andar ordenadamente, conducirse conforme a una norma o regla; seguir un curso de vida disciplinado.', 'Derivado de la imagen de soldados formados en fila, este verbo evoca el caminar acompasado o el mantenerse alineado con un principio rector. En el Nuevo Testamento describe consistentemente el ajustar la conducta a una norma espiritual, ya sea la regla de fe (Gá 6:16) o la guía del Espíritu (Gá 5:25). Pablo lo emplea para exhortar a los creyentes a ''marchar al paso'' de lo que ya han alcanzado (Fil 3:16). La expresión española ''andar ordenadamente'' capta con precisión este sentido de caminar disciplinado y con propósito, mientras que ''seguir las pisadas'' refleja el matiz de imitar un ejemplo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4749', 'spa', 'Vestidura larga y suelta; ropaje formal exterior asociado con dignidad, honor o condición celestial.', 'Στολή designa una vestidura exterior larga y suelta que denota estatus o solemnidad. En el griego clásico abarcaba desde equipamiento militar hasta indumentaria cotidiana, pero en el Nuevo Testamento señala consistentemente un ropaje de honor o distinción. Los escribas anhelan pasear con vestiduras largas como marca de prestigio (Mr 12:38; Lc 20:46), el hijo pródigo es revestido con «la mejor vestidura» al ser restaurado (Lc 15:22), el ángel en el sepulcro vacío lleva una vestidura blanca (Mr 16:5), y los mártires bajo el altar reciben vestiduras blancas (Ap 6:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4750', 'spa', 'Boca: el organo fisico del habla y la alimentacion, y por metonimia las palabras o el testimonio pronunciados.', 'El griego στόμα se refiere a la boca como organo fisico y, por extension natural, al habla y el testimonio que de ella proceden. Jesus declara que lo que contamina al hombre sale de la boca, no lo que entra en ella (Mateo 15:11), haciendo de στόμα el lugar de la autorrevelacion moral. La frase ''de la boca de los ninos'' (Mateo 21:16, citando Salmo 8:2) muestra el salto metonimico del organo a la palabra. En Apocalipsis, una espada aguda sale de la boca de Cristo (Apocalipsis 1:16), imagen donde el organo fisico y la palabra divina se fusionan. La traduccion es directa — en espanol boca — pero los usos teologicos trascienden con mucho lo anatomico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4753', 'spa', 'Ejército, fuerza militar, cuerpo de tropas desplegado para campaña o aplicación de la ley.', 'Στράτευμα designa un cuerpo militar organizado, desde un ejército completo hasta un destacamento de soldados. En Mateo 22:7, un rey envía sus «ejércitos» para destruir a los homicidas e incendiar su ciudad, imagen parabólica del juicio divino. Lucas 23:11 registra a Herodes y sus soldados burlándose de Jesús. En Hechos, tropas romanas intervienen para rescatar a Pablo de la violencia de la turba (Hch 23:10, 27). Apocalipsis 9:16 visualiza una fuerza de caballería asombrosa de doscientos millones. El vocablo evoca consistentemente el poder militar sancionado por el Estado, ya sea desplegado en la narrativa histórica o en la visión apocalíptica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4754', 'spa', 'Servir como soldado o hacer guerra; usado tanto literalmente del servicio militar como metafóricamente del conflicto espiritual y moral.', 'Στρατεύομαι abarca todo el arco del oficio militar — desde el alistamiento literal hasta la guerra metafórica. Cuando los soldados se acercan a Juan el Bautista (Lucas 3:14), la forma participial ''los que sirven como soldados'' simplemente describe su profesión. Pablo también trata el servicio militar como analogía familiar: ¿quién sirve como soldado a sus propias expensas? (1 Corintios 9:7). Sin embargo, los usos de mayor carga teológica son metafóricos. En 2 Corintios 10:3 Pablo insiste en que ''no militamos según la carne'', mientras que Santiago 4:1 rastrea los conflictos hasta las pasiones que ''combaten'' en nuestro interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4755', 'spa', 'Un comandante militar o magistrado cívico, usado para referirse a los capitanes del templo y a los oficiales de la ciudad. Designa a una persona que o', 'Un comandante militar o magistrado cívico, usado para referirse a los capitanes del templo y a los oficiales de la ciudad. Designa a una persona que ocupa una posición de autoridad militar o cívica. En los escritos de Lucas aparece en dos contextos institucionales distintos: el capitán de la guardia del templo, quien comandaba la fuerza policial levítica responsable del orden en los recintos del templo (Lucas 22:4, 52; Hechos 4:1; 5:24, 26), y los magistrados coloniales romanos de Filipos que ordenaron azotar y encarcelar a Pablo y Silas (Hechos 16:20, 22, 35, 36, 38). El término tiende así un puente entre la autoridad religiosa judía y la gobernanza cívica grecorromana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4757', 'spa', 'soldado — un militar, especialmente un soldado romano en las narraciones de los Evangelios y Hechos', 'soldado — un militar, especialmente un soldado romano en las narraciones de los Evangelios y Hechos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4762', 'spa', 'Volverse, girar o regresar; de reorientación física, conversión espiritual, redirección de algo, o devolución de lo recibido', 'Volverse, girar o regresar; de reorientación física, conversión espiritual, redirección de algo, o devolución de lo recibido');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4765', 'spa', 'Gorrión; ave pequeña y común usada en las Escrituras para ilustrar el cuidado de Dios por las criaturas más insignificantes', 'Diminutivo del término griego más amplio para ave (στρουθός), que designa específicamente al gorrión, una de las aves más corrientes y baratas que se vendían en los mercados palestinos. Jesús invoca al gorrión en Mateo 10:29-31 y Lucas 12:6-7 para construir un argumento impactante de menor a mayor: si Dios vigila el destino de una criatura que vale medio centavo, ¡cuánto más velará por sus hijos! Las traducciones en múltiples lenguas convergen con precisión —español «gorriones», francés «moineau»— confirmando un sentido único y estable en las cuatro ocurrencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4766', 'spa', 'Extender, esparcir (mantos, ramas); amueblar o preparar (una sala); hacer (una cama).', 'Στρώννυμι es un verbo cotidiano y concreto cuyo significado básico es extender algo sobre una superficie plana. Los Evangelios lo emplean vívidamente en la entrada triunfal: las multitudes ''extendieron'' (ἔστρωσαν) sus mantos y ''tendían'' (ἐστρώννυον) ramas por el camino ante Jesús (Mat 21:8; Mar 11:8). El mismo verbo adquiere un matiz doméstico al describir el aposento alto ''amueblado'' (ἐστρωμένον) para la Última Cena (Mar 14:15; Luc 22:12). En Hechos 9:34, Pedro ordena al sanado Eneas: ''hazte tu cama'' (στρῶσον σεαυτῷ), el uso más íntimo y personal de esta acción de extender.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4769', 'spa', 'Columna o pilar; soporte vertical usado literalmente en arquitectura y metafóricamente de personas o instituciones que sostienen la verdad', 'Designa un soporte estructural vertical —un pilar o columna— que sostiene el peso de un edificio. En el NT, el sentido arquitectónico literal cede ante poderosos usos metafóricos. Pablo llama a Jacobo, Cefas y Juan «columnas» de la iglesia de Jerusalén (Gá 2:9); la iglesia misma es «columna y baluarte de la verdad» (1 Tim 3:15), y el creyente glorificado se convierte en columna permanente en el templo de Dios (Ap 3:12). El único caso fronterizo entre lo literal y lo metafórico es Apocalipsis 10:1, donde las piernas de un ángel se comparan con columnas de fuego, evocando la columna de nube y fuego del Éxodo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4771', 'spa', 'Pronombre de segunda persona: ''tu'' (singular) y ''vosotros'' (plural), en todos los casos gramaticales.', 'El pronombre de segunda persona σύ abarca tanto el singular como el plural en todos los casos griegos: nominativo, genitivo, dativo y acusativo. Las lenguas que conservan la distincion singular/plural la iluminan con claridad: el espanol usa ''de ti'' para el singular pero ''de vosotros'' y ''os'' para el plural; el frances distingue ''de toi'' de ''vous''; el aleman contrasta ''deiner'' con ''euch.'' La forma plural domina (unas 1.850 apariciones), a menudo en la ensenanza colectiva de Jesus a discipulos o multitudes, mientras la forma singular (unas 1.077 apariciones) surge en intercambios intimos o de confrontacion, como las palabras del angel a Jose (Mt 1:20) o la reprension de Jesus a Satanas (Mt 4:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4772', 'spa', 'Parentela, parientes, familia; el grupo familiar extenso o red de vínculos de consanguinidad', 'Sustantivo que designa el parentesco, los lazos familiares o el conjunto de parientes. Lucas lo emplea cuando los vecinos cuestionan el nombre de Juan porque «ninguno de tu parentela se llama así» (1:61). En Hechos, Dios ordena a Abraham dejar su «parentela» (7:3), y José manda llamar a su «parentela» —setenta y cinco personas— a Egipto (7:14). La palabra abarca toda la red familiar extendida, el tejido de relaciones de sangre que definía la identidad y las obligaciones en la cultura mediterránea antigua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4773', 'spa', 'El adjetivo συγγενής (''de la misma familia''), usado como sustantivo con el significado de ''pariente'' o ''familiar'', designa a una persona unida a otra ', 'El adjetivo συγγενής (''de la misma familia''), usado como sustantivo con el significado de ''pariente'' o ''familiar'', designa a una persona unida a otra por sangre o linaje. Elisabet es llamada pariente de María (Lucas 1:36), y los familiares se alegran por el nacimiento de Juan el Bautista (Lucas 1:58). Jesús observa que ''un profeta no carece de honra sino entre sus propios parientes'' (Marcos 6:4). Pablo extiende el término hacia el parentesco étnico al hablar de sus ''parientes según la carne'' (Romanos 9:3) y saludar a creyentes judíos como ''mis parientes'' (Romanos 16:7, 11, 21). Cornelio reúne a sus parientes antes de la llegada de Pedro (Hechos 10:24). Ya sea un vínculo familiar inmediato o un linaje étnico extendido, el sentido subyacente permanece como el de una descendencia compartida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4779', 'spa', 'Convocar, reunir, llamar a juntarse: congregar personas para una asamblea o reunión con propósito definido.', 'Compuesto de σύν (''juntos'') y καλέω (''llamar''), συγκαλέω significa convocar a personas para que se reúnan en asamblea. En el NT aparece tanto en voz activa como en voz media. Los soldados de Pilato ''convocaron'' a toda la cohorte para burlarse de Jesús (Marcos 15:16). Jesús ''convocó'' a los Doce para darles autoridad (Lucas 9:1). Notablemente, las parábolas de la oveja perdida y la moneda perdida emplean este verbo para la gozosa convocatoria de amigos y vecinos a celebrar el hallazgo (Lucas 15:6, 9). En Hechos 5:21 se convoca formalmente al Sanedrín. La palabra señala siempre una reunión intencional y deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4788', 'spa', 'Encerrar, confinar, atrapar; usado para atrapar peces en una red y para Dios sujetando a todos bajo pecado o ley', 'Verbo compuesto (σύν + κλείω, «cerrar juntamente») que significa encerrar, acorralar o confinar por todos lados. Su uso en el NT abarca una vívida escena literal y una profunda metáfora teológica. En Lucas 5:6 describe la pesca milagrosa en la que los peces quedan encerrados en una red a punto de romperse. Pablo despliega el mismo verbo teológicamente en Romanos 11:32 y Gálatas 3:22-23: Dios ha «encerrado» a todos bajo la desobediencia o bajo la ley para que la misericordia y la fe sean la única salida. La distinción en español entre «encerraron» (activa) y «siendo encerrados» (pasiva) refleja la dinámica teológica activo-pasiva del original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4789', 'spa', 'Coheredero; quien comparte una herencia juntamente con otro, especialmente como coherederos con Cristo.', 'Adjetivo compuesto (σύν + κληρονόμος) que designa a quien hereda conjuntamente con otro. Las cuatro apariciones en el NT portan una carga teológica profunda. En Romanos 8:17, los creyentes son «coherederos con Cristo», compartiendo su gloria si comparten sus padecimientos. Efesios 3:6 extiende el concepto a los gentiles como coherederos de la promesa. Hebreos 11:9 lo aplica a los patriarcas que compartían la misma promesa, y 1 Pedro 3:7 lo lleva al ámbito doméstico: esposos y esposas como coherederos de la gracia de la vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4790', 'spa', 'Participar juntamente en, compartir en comunión; tener parte en algo, a menudo con implicaciones morales', 'Verbo compuesto que significa participar conjuntamente en algo, tener comunión o asociación compartida. Pablo advierte contra participar en las «obras infructuosas de las tinieblas» (Ef 5:11), elogia a los filipenses por compartir en su aflicción (Fil 4:14), y Apocalipsis advierte contra participar en los pecados de Babilonia (18:4). El prefijo συν- (junto) resalta que la participación compartida crea comunidad: uno se hace cómplice o se une a aquello en lo que participa, ya sea para mal o para bien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4791', 'spa', 'Copartícipe; quien participa conjuntamente con otros en algo, ya sea sufrimiento, gracia o promesa.', 'Sustantivo compuesto (σύν + κοινωνός) que significa participante conjunto o copartícipe. Mientras que συγκληρονόμος (G4789) se centra en la herencia, συγκοινωνός enfatiza la participación activa en una experiencia o empresa común. Pablo lo usa para describir a los gentiles injertados en la «raíz y la riqueza» de Israel (Rom 11:17), su propia asociación con el evangelio (1 Cor 9:23), la participación compartida de los filipenses en la gracia (Fil 1:7), y Juan lo emplea para su comunión con sus lectores en la tribulación, el reino y la paciencia (Ap 1:9). El término transmite solidaridad mediante la experiencia compartida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4793', 'spa', 'Comparar, combinar o interpretar conjuntamente; poner cosas en relación para evaluar o explicar', 'Verbo que significa comparar, combinar o poner cosas juntas para examinarlas. Aparece en 1 Corintios 2:13, donde Pablo explica verdades espirituales «combinando lo espiritual con lo espiritual», y dos veces en 2 Corintios 10:12, donde Pablo rehúsa compararse con quienes se alaban a sí mismos y «se miden unos a otros por sí mismos». Los usos del NT abarcan tanto la síntesis interpretativa —hacer coincidir el contenido espiritual con la expresión espiritual— como la comparación evaluativa —medir personas según un estándar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4796', 'spa', 'Regocijarse juntamente con alguien; compartir el gozo de otro o felicitarlo por una ocasión dichosa.', 'Denota el acto de unirse a la alegría de otra persona, ya sea por un nacimiento, la recuperación de algo perdido o una celebración comunitaria. En Lucas 15, tanto el pastor como la mujer que encuentra su moneda perdida llaman a los vecinos a ''gozarse conmigo'', subrayando la dimensión comunitaria de la invitación. Pablo extiende la idea más allá de las festividades sociales hacia la vida del cuerpo de Cristo: cuando un miembro es honrado, todos se gozan juntamente (1 Corintios 12:26), y el amor mismo ''se goza con la verdad'' (1 Corintios 13:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4797', 'spa', 'Confundir, causar tumulto; desconcertar o provocar alboroto entre la gente.', 'Este verbo expresivo significa literalmente ''verter junto'' o ''mezclar'', pero en Hechos describe de manera consistente la conmoción social y psicológica causada por acontecimientos inesperados. Cuando la multitud en Pentecostés oyó hablar sus propias lenguas, quedó ''confundida'' (Hch 2:6). La poderosa predicación de Saulo desconcertó a los judíos de Damasco (Hch 9:22), y el caos de las turbas en Éfeso y Jerusalén muestra la capacidad del término para abarcar tanto el desconcierto interior como el tumulto exterior. El español capta ambas dimensiones con ''confundir'' para la perplejidad y ''alborotar'' para el desorden público.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4800', 'spa', 'Vivir juntamente con, compartir la vida con alguien; coexistir en vida común', 'Verbo compuesto que significa vivir juntamente con alguien, compartir una vida en común. Pablo lo usa tres veces: «si morimos con Cristo, creemos que también viviremos con él» (Ro 6:8, 2 Ti 2:11), y al declarar que los corintios están en su corazón «para morir juntos y para vivir juntos» (2 Co 7:3). El verbo combina «junto» (συν-) con «vivir» (ζάω), enfatizando no solo cercanía sino existencia compartida. Los usos paulinos vinculan siempre el vivir juntos con el morir juntos: los creyentes unidos a Cristo en su muerte comparten su vida de resurrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4802', 'spa', 'Debatir o discutir juntos; abarca desde la disputa hostil con oponentes hasta la indagación colaborativa entre compañeros. Verbo compuesto (σύν + ζητέ', 'Debatir o discutir juntos; abarca desde la disputa hostil con oponentes hasta la indagación colaborativa entre compañeros. Verbo compuesto (σύν + ζητέω, ''buscar juntos'') que capta todo el espectro del intercambio verbal conjunto. En los Evangelios aparece tanto en contextos hostiles —los escribas disputando con los discípulos de Jesús al pie del Monte de la Transfiguración (Marcos 9:14, 16)— como en momentos de reflexión, cuando los discípulos de Emaús ''discutían entre sí'' los eventos de la muerte de Jesús (Lucas 24:15). El español traduce ambos sentidos consistentemente con ''discutir'', confirmando una idea raíz compartida de intercambio enérgico cuyo tono lo determina el contexto y no el verbo en sí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4808', 'spa', 'Higuera (Ficus carica); un arbol frutal comun en el Mediterraneo, usado literalmente y como simbolo de la condicion espiritual de Israel. συκῆ se refi', 'Higuera (Ficus carica); un arbol frutal comun en el Mediterraneo, usado literalmente y como simbolo de la condicion espiritual de Israel. συκῆ se refiere a la higuera comun, una de las plantas mas caracteristicas del paisaje biblico. Jesus maldice una higuera esteril camino a Jerusalen, y esta se seca de la noche a la manana, una parabola en accion sobre el juicio contra el Israel infructuoso (Mt 21:19-21; Mc 11:13-21). La higuera tambien sirve como senal estacional: cuando sus ramas se ablandan y brotan hojas, el verano esta cerca, asi como ciertas senales anuncian la venida del Hijo del Hombre (Mt 24:32; Mc 13:28). Natanael es hallado sentado bajo una higuera (Jn 1:48-50), evocando un escenario tradicional para el estudio de la Tora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4810', 'spa', 'Higo; el fruto de la higuera, usado literalmente y como metáfora de la correspondencia entre naturaleza y carácter.', 'La palabra griega común para el fruto de la higuera (συκῆ). Los higos eran un alimento básico en el Mediterráneo antiguo y tenían un significado proverbial. Jesús los emplea en enseñanzas sobre discernir el verdadero carácter a partir del fruto visible: «¿Acaso se recogen higos de los espinos?» (Mt 7:16; Lc 6:44). Marcos 11:13 narra la maldición de la higuera estéril, donde Jesús buscó higos y no halló ninguno. Santiago 3:12 pregunta si una higuera puede producir aceitunas o una vid higos, ilustrando la imposibilidad de un fruto moral mixto de una sola fuente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4814', 'spa', 'Hablar con o entre sí; conversar o deliberar, desde el intercambio informal hasta la consulta oficial.', 'Συλλαλέω es un compuesto de σύν (juntos) y λαλέω (hablar) — en esencia, significa hablar con alguien o entre un grupo. En el Monte de la Transfiguración, Moisés y Elías están ''hablando'' con Jesús (Mat 17:3; Mar 9:4; Luc 9:30), y en Capernaúm la multitud asombrada habla entre sí sobre la autoridad de Jesús (Luc 4:36). Pero el término también puede tener peso oficial: en Hechos 25:12, Festo ''confiere'' con su consejo antes de dictar una decisión judicial. El español distingue bien ambos registros: ''conversar'' o ''hablar con'' para el intercambio informal, y ''conferir'' para la deliberación formal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4815', 'spa', 'Prender, arrestar o capturar (fisicamente); concebir o quedar embarazada; ayudar o asistir (tomar juntos). Pocos verbos griegos cubren un rango semant', 'Prender, arrestar o capturar (fisicamente); concebir o quedar embarazada; ayudar o asistir (tomar juntos). Pocos verbos griegos cubren un rango semantico tan sorprendente como συλλαμβάνω — ''tomar juntos''. Su nucleo literal de agarrar y prender domina las narrativas de la pasion: los soldados prenden a Jesus en Getsemani (Mt 26:55; Lc 22:54; Jn 18:12), y Pedro es arrestado por Herodes (Hch 12:3). Sin embargo, Lucas elige este mismo verbo para el mas intimo de los comienzos: Maria ''concebira'' un hijo (Lc 1:31), Elisabet ''ha concebido'' en su vejez (Lc 1:36), y el pecado ''concibe'' y da a luz la muerte (Stg 1:15). El sentido mas raro, ''ayudar'', preserva el prefijo συν- con mayor transparencia: los companeros ''toman juntos'' para recoger la pesca (Lc 5:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4816', 'spa', 'Recoger, juntar, cosechar: reunir cosas dispersas, especialmente en contextos de siega y cosecha.', 'El verbo συλλέγω significa recoger o juntar elementos dispersos, y en el NT se emplea casi exclusivamente en contextos agrícolas y parabólicos. Jesús pregunta retóricamente si acaso se recogen uvas de los espinos o higos de los abrojos (Mateo 7:16; Lucas 6:44). La parábola del trigo y la cizaña presenta este verbo de manera prominente: los siervos preguntan si deben arrancar la cizaña, y en la cosecha los ángeles la recogerán para quemarla (Mateo 13:28-30, 40-41). La parábola de la red también recoge los peces buenos en cestas (Mateo 13:48). La palabra evoca una recolección cuidadosa y deliberada que distingue lo valioso de lo que no lo es.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4819', 'spa', 'Suceder, acontecer, ocurrir: eventos que sobrevienen a una persona o que llegan a cumplirse.', 'Originalmente con el sentido de ''caminar juntos'' o ''encontrarse'', συμβαίνω evolucionó hasta convertirse en un término estándar del griego para referirse a eventos que suceden o llegan a cumplirse. En el NT describe de manera consistente sucesos dignos de nota. Los dos discípulos camino a Emaús conversan sobre ''las cosas que habían sucedido'' (Lucas 24:14). Pablo relata ''lo que me ha sobrevenido'' a través de pruebas (Hechos 20:19). Pedro exhorta a los creyentes a no sorprenderse de la ''prueba de fuego que les sobreviene'' (1 Pedro 4:12). Pablo extrae lecciones tipológicas de lo que ''sucedió'' a Israel como ejemplo para la iglesia (1 Corintios 10:11). El verbo enmarca los acontecimientos como significativos, no meramente casuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4820', 'spa', 'Reunir, juntar; de ahí conferir, encontrarse, contribuir con ayuda o meditar interiormente.', 'Συμβάλλω significa literalmente ''lanzar juntos'', y sus usos en el Nuevo Testamento se despliegan bellamente a partir de esa imagen raíz. Filósofos en Atenas ''intercambian palabras'' con Pablo en un debate (Acts 17:18); un rey evalúa si puede ''enfrentar'' a un ejército que se aproxima (Luke 14:31); Apolos ''aporta su parte'' para ayudar a los creyentes de Acaya (Acts 18:27); y María ''junta en su corazón'' las cosas asombrosas que los pastores reportaron (Luke 2:19). Un solo verbo griego que conecta el encuentro externo con la reflexión interna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4822', 'spa', 'Unir, entrelazar; instruir; presentar; demostrar; concluir — del sentido físico de ''juntar'' al intelectual de ''razonar''', 'Un verbo griego de gran riqueza semántica cuyo significado raíz es ''reunir'' o ''juntar'', pero cuyos usos neotestamentarios abarcan desde la unión física hasta la instrucción intelectual, la demostración lógica y la inferencia razonada. Pablo lo emplea teológicamente para describir el cuerpo de Cristo ''entrelazado'' en amor (Col 2:2; Ef 4:16), evocando la imagen de ligamentos que unen huesos. Sin embargo, el mismo verbo puede significar instruir a alguien ''poniendo las cosas en orden'' (1 Co 2:16, citando Is 40:13 LXX), demostrar un argumento reuniendo evidencias (Hch 9:22), o sacar una conclusión a partir de una visión (Hch 16:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4823', 'spa', 'Aconsejar, deliberar; usado tanto para dar orientación como para conspirar en planes hostiles.', 'Verbo que significa dar consejo o asesoramiento, con un rango semántico que abarca desde la recomendación benévola hasta la conspiración hostil. La misma palabra describe el cálculo político de Caifás (Jn 18:14) y la trama contra Jesús (Mt 26:4), así como la conspiración de Damasco contra Pablo (Hch 9:23) y el consejo misericordioso de Cristo a la iglesia de Laodicea de comprar oro refinado (Ap 3:18). Solo el contexto determina si el consejo es constructivo o destructivo, lo que lo convierte en un sentido único con fuerte polaridad contextual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4824', 'spa', 'Consejo, consulta, conspiración; un consejo de asesores o cuerpo consultivo oficial.', 'El sustantivo συμβούλιον abarca dos sentidos relacionados pero distinguibles, ambos enraizados en la idea de deliberación. Con mayor frecuencia en el NT designa el acto de tomar consejo o tramar un complot: una confabulación de voluntades más que un cuerpo formal. Los fariseos ''tomaron consejo'' contra Jesús (Mateo 12:14), conspiraron para tenderle una trampa (Mateo 22:15), y los principales sacerdotes ''deliberaron'' para darle muerte (Mateo 27:1). Sin embargo, en una única aparición en Hechos 25:12 se refiere al consejo consultivo que acompañaba al gobernador romano Festo, un término técnico para el consilium de la administración provincial romana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4826', 'spa', 'Simeón — nombre propio hebreo (de שִׁמְעוֹן, ''el que oye'') que llevan varios personajes del NT, incluido el anciano devoto y el apóstol Pedro.', 'Forma griega indeclinable del nombre hebreo שִׁמְעוֹן (que significa ''el que oye''), usada en el NT para al menos cinco individuos distintos. El más memorable es el anciano piadoso que tomó al niño Jesús en sus brazos en el templo y pronunció el Nunc Dimittis (Lc 2:25, 34). También designa a Simeón llamado Níger en la iglesia de Antioquía (Hch 13:1) y sirve como forma más hebraica del nombre de Simón Pedro, como cuando Santiago lo usa en el concilio de Jerusalén (Hch 15:14) y en la apertura de 2 Pedro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4828', 'spa', 'Dar testimonio conjuntamente, testificar junto con otro; corroborar un testimonio anadiendo el propio', 'Verbo compuesto que significa dar testimonio junto con otro, co-testificar. Pablo lo emplea tres veces: la ley y la conciencia «dan testimonio juntamente» del conocimiento moral de los gentiles (Ro 2:15), el Espiritu «da testimonio con nuestro espiritu» de que somos hijos de Dios (8:16), y la conciencia de Pablo «da testimonio con el» en el Espiritu (9:1). El prefijo συν- subraya la corroboracion: dos testigos confirmando una misma realidad. En el uso clasico incluye respaldar el testimonio de otro o estar en aspecto astrologico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4838', 'spa', 'Llevar consigo; traer a alguien como compañero o asistente en un viaje o misión.', 'Verbo compuesto (σύν + παρά + λαμβάνω) que significa llevar a alguien consigo como compañero. Las cuatro apariciones en el NT se relacionan con asociaciones de viaje misionero en la iglesia primitiva. El término aparece en una coyuntura narrativa clave: Bernabé y Saulo llevan consigo a Juan Marcos desde Jerusalén (Hch 12:25), Bernabé después quiere llevarlo de nuevo (Hch 15:37), Pablo se niega porque Marcos los había abandonado (Hch 15:38), y Pablo lleva consigo a Tito al concilio de Jerusalén (Gá 2:1). El verbo implica consistentemente la selección deliberada de un compañero de viaje para una misión compartida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4839', 'spa', 'permanecer con, quedarse al lado de, perseverar junto a; continuar en compañía de alguien o persistir ante las circunstancias', 'Este verbo compuesto significa permanecer junto a alguien o quedarse con esa persona a través de circunstancias difíciles. El prefijo συν- añade el sentido de compañerismo o experiencia compartida al significado básico de ''permanecer''. Los autores clásicos lo usaban para describir a una mujer que permanecía con su esposo durante la adversidad, demostrando lealtad en tiempos difíciles. También podía significar resistir mientras durara la vida misma, mantenerse firme durante toda la duración de algo. La palabra enfatizaba la presencia fiel más que la mera cercanía física: estar al lado de alguien cuando otros lo abandonarían, o persistir cuando las circunstancias invitaban a marcharse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4845', 'spa', 'Llenar completamente, cumplirse; llegar a plenitud, especialmente de tiempos o propositos senalados', 'Verbo que significa llenar por completo, cumplir o llevar a plenitud. Lucas lo usa tres veces: la barca «se llenaba» de agua (8:23), «se cumplian los dias» de la ascension de Jesus (9:51), y «al cumplirse el dia de Pentecostes» (Hch 2:1). Combina συν- («junto») con «llenar», enfatizando el llenado total o la llegada de un tiempo predeterminado. En el uso clasico incluye tripular naves, rellenar huecos, completar cuotas y causar congestion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4846', 'spa', 'Ahogar, apretar en derredor hasta sofocar; dicho de espinos que ahogan la semilla y de multitudes que oprimen a una persona.', 'Con el sentido literal de comprimir hasta cortar la respiración, este verbo aparece casi exclusivamente en la parábola del sembrador y sus explicaciones. Los espinos crecen y ''ahogan'' la semilla, impidiéndole dar fruto (Mt 13:22; Mc 4:7, 19; Lc 8:14). Lucas también lo emplea para describir la presión física de la multitud alrededor de Jesús (Lc 8:42). El español ''ahogar'' comunica vívidamente la fuerza aniquiladora de la imagen, ya se trate del agolpamiento literal o del sofocamiento figurado de la palabra por las preocupaciones del mundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4848', 'spa', 'Ir o viajar junto con alguien; acompañar, o congregarse y caminar en grupo como multitud.', 'Verbo compuesto (σύν + πορεύομαι) que significa viajar juntos o acompañar a alguien en el camino. En el Evangelio de Lucas, esta palabra capta la cualidad comunitaria y procesional del ministerio de Jesús: las multitudes «iban con» Él (Lucas 7:11; 14:25), y los dos discípulos de Emaús caminaron junto al Cristo resucitado sin reconocerlo (Lucas 24:15). Marcos 10:1 lo usa para describir a las multitudes que se reunían y viajaban con Jesús. El término transmite compañía en el camino, ya sea íntima o multitudinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4851', 'spa', 'Reunir, juntar; impersonalmente, ser provechoso, beneficioso o conveniente — lo que es ventajoso o conviene a los intereses de alguien. Compuesto de σ', 'Reunir, juntar; impersonalmente, ser provechoso, beneficioso o conveniente — lo que es ventajoso o conviene a los intereses de alguien. Compuesto de συν (''juntos'') y φέρω (''llevar, traer''), este verbo tiene un sentido literal de reunir o recoger cosas en un solo lugar, y un sentido impersonal derivado de ''es provechoso'' o ''conviene''. El Nuevo Testamento usa abrumadoramente el sentido impersonal: ''Os conviene que un solo hombre muera por el pueblo'' (Jn 11:50; 18:14), ''Todo es licito pero no todo es provechoso'' (1 Co 6:12; 10:23). Solo una vez, en Hechos 19:19, aparece el sentido espacial literal, cuando los convertidos efesios ''trajeron'' sus libros de hechiceria para quemarlos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4856', 'spa', 'συμφωνέω — concordar, armonizar, estar de acuerdo; de σύν + φωνή (''sonar juntos'').', 'Formado a partir de σύν (''juntos'') y φωνή (''voz, sonido''), συμφωνέω significa literalmente ''sonar juntos en armonía'', la raíz del español ''sinfonía''. En el Nuevo Testamento denota consistentemente llegar a un acuerdo o estar en concordancia. Jesús promete que ''si dos de ustedes se ponen de acuerdo en la tierra acerca de cualquier cosa que pidan, les será hecho'' (Matt 18:19). En la parábola de los obreros de la viña, el amo ''acordó con'' los trabajadores un denario al día (Matt 20:2, 13). Luke 5:36 lo usa para parches de tela que no ''combinan'', y Acts 5:9 pregunta por qué Ananías y Safira ''se pusieron de acuerdo'' para tentar al Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4862', 'spa', 'Con — preposición que expresa compañía, asociación, acción conjunta o presencia combinada.', 'σύν es la preposición griega clásica para ''con,'' que denota compañía y participación conjunta. En el Nuevo Testamento aparece 129 veces, frecuentemente en contextos de asociación íntima: ser crucificado ''con'' Cristo (Romanos 6:6), ser sepultado y resucitado ''con'' él (Colosenses 2:12-13), o la promesa de vivir ''con'' él para siempre (1 Tesalonicenses 4:17). Mientras que μετά con genitivo se solapa en significado, σύν tiende a enfatizar una unidad más estrecha y una experiencia compartida. Su prolífico uso en verbos compuestos (συνάγειν, συνεργεῖν, συμπαθεῖν) muestra cuán profundamente el concepto de unión impregna la expresión griega. El español ''con,'' el francés ''avec'' y el alemán ''mit'' funcionan como equivalentes regulares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4863', 'spa', 'Reunir o congregar; de personas que se juntan; de acoger a forasteros con hospitalidad.', 'Formado a partir de σύν (''juntos'') y ἄγω (''conducir''), este verbo evoca la accion de congregar personas o cosas en un mismo lugar. Aparece en los Evangelios tanto para multitudes que se reunen en torno a Jesus como para actos deliberados de recoger: cosechar trigo en graneros (Mateo 3:12; 6:26) o convocar concilios (Mateo 2:4). Un notable sentido extendido surge en Mateo 25:35, donde ''recoger'' a un forastero se convierte en un acto de hospitalidad: el espanol ''me recogisteis'' revela la calidez contenida en esta palabra, que va mucho mas alla del mero congregarse fisico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4864', 'spa', 'Sinagoga: la asamblea judia o su lugar de reunion para culto, oracion y lectura de las Escrituras.', 'El sustantivo femenino συναγωγή, de σύν (''juntos'') y ἄγω (''conducir''), designa tanto la asamblea reunida como el edificio fisico donde los judios se congregaban para el culto, la oracion y la lectura de las Escrituras. Para el siglo primero se habia convertido en el centro de la vida comunitaria judia tanto en Palestina como en la Diaspora. Jesus inicio su ministerio publico en sinagogas (Mateo 4:23; Lucas 4:16-21), Pablo comenzaba su labor misionera en ellas (Hechos 13:5; 17:1-2) y sirven como escenarios de sanaciones, controversias y persecuciones. El espanol sinagoga deriva directamente del mismo compuesto griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4867', 'spa', 'Reunir, congregar; juntar personas o cosas en un solo grupo o lugar', 'Verbo compuesto que significa reunir o congregar, juntar en un solo grupo. Lucas lo emplea tres veces: los discipulos «se reunieron» en Jerusalen tras la resurreccion (24:33), la reunion de oracion de Maria esta «congregada» cuando Pedro llama (Hch 12:12), y Pablo «reunio» a los artesanos y obreros en Efeso (19:25). El prefijo συν- enfatiza la asamblea colectiva: traer a un mismo lugar a individuos dispersos. En el uso clasico incluye reunir tropas, acopiar materiales o unirse al grueso del ejercito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4868', 'spa', 'Ajustar cuentas, hacer un balance conjunto; realizar una rendicion financiera o relacional y saldar deudas', 'Verbo que significa ajustar cuentas, hacer balance o saldar. Los tres usos neotestamentarios aparecen en parabolas de Mateo: el reino es como un rey que «ajusto cuentas» con sus siervos (18:23), al comenzar a ajustar uno le debia diez mil talentos (18:24), y el senor «ajusto cuentas» con sus siervos (25:19). Combina συν- («junto») con «tomar/calcular», subrayando el proceso mutuo de revisar deudas y creditos y emitir un juicio final sobre lo adeudado. En el uso clasico incluye recoger cosechas o reunir bienes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4869', 'spa', 'Companero de prision, copreso; alguien que comparte el cautiverio o encarcelamiento con otro', 'Sustantivo compuesto que significa companero de prision, alguien que comparte el cautiverio. Pablo lo usa tres veces: Andronico y Junias son «mis companeros de prision» (Ro 16:7), Aristarco es «mi companero de prision» (Col 4:10), y Epafras saluda como «mi companero de prision en Cristo Jesus» (Flm 23). El termino transmite mas que proximidad fisica: implica sufrimiento compartido por el evangelio, vinculos forjados en la afliccion y el honor de llevar cadenas por Cristo. No eran simples companeros de celda, sino hermanos unidos en el testimonio del evangelio mediante la prision.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4870', 'spa', 'Seguir juntamente con, acompañar; seguir de cerca a alguien o atender algo con dedicación', 'Verbo compuesto que significa seguir juntamente con otro, acompañar o seguir de cerca. Marcos lo emplea para describir a las mujeres que «seguían con» Jesús desde Galilea (Mr 5:37), al joven que «le seguía» tras el arresto (14:51), y a las mujeres que «habían seguido con» Jesús y presenciaron la crucifixión (Lc 23:49). El prefijo συν- subraya la idea de acompañamiento en el camino. En el uso clásico abarca seguir a un ejército, rastrear un argumento o consecuencias que se derivan de causas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4873', 'spa', 'Reclinarse a la mesa junto con alguien; compartir una comida como comensal en la postura antigua de banquete.', 'Se refiere a la costumbre antigua de reclinarse en divanes durante una comida comunitaria, subrayando la comunión de mesa compartida. Cuando Jesús come con publicanos y pecadores (Mt 9:10; Mr 2:15), el verbo resalta el escándalo de la proximidad social íntima: reclinarse juntos implicaba aceptación y solidaridad. El término aparece en banquetes y fiestas donde la identidad de los compañeros de mesa tenía un peso social y religioso significativo. En español se traduce como ''reclinados con'' o ''estar a la mesa con'', preservando la dimensión física y relacional de la postura compartida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4874', 'spa', 'Asociarse con, mezclarse con otros; mantener trato social o convivir estrechamente con alguien', 'Verbo compuesto que significa mezclarse con otros, asociarse o mantener trato con alguien. Pablo lo usa tres veces respecto a los límites de la comunidad cristiana: «os escribí que no os juntéis con los inmorales» (1 Co 5:9), «ni siquiera comáis con tal persona» (5:11), y «no os asociéis con» quien desobedezca su carta (2 Ts 3:14). El verbo combina συν- («junto con») y «mezclar», enfatizando la convivencia social. En el uso clásico incluía mezclar sustancias o el encuentro de grupos de personas. Pablo aborda así los límites de la pureza comunitaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4876', 'spa', 'Encontrarse o toparse con alguien cara a cara; por extensión, de eventos o circunstancias que le sobrevienen a una persona.', 'Συναντάω combina σύν (''juntos'') y ἀντάω (''venir al frente'') para representar a dos partes que llegan cara a cara. En los Evangelios aparece cuando una multitud sale al encuentro de Jesús al descender del monte (Luke 9:37) y cuando un hombre con un cántaro de agua saldrá al encuentro de los discípulos en Jerusalén (Luke 22:10). Su aparición teológicamente más rica está en Heb 7:1, donde Melquisedec se encuentra con Abraham que regresaba de la batalla, un encuentro cargado de significado tipológico. Pero la palabra también se extiende más allá de encuentros físicos: en Acts 20:22, Pablo habla de las cosas que le ''saldrán al encuentro'' en Jerusalén, es decir, eventos que le sobrevendrán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4877', 'spa', 'encuentro, reunión; acto de encontrarse con alguien, ya sea casual o concertado, o conjunción celeste', 'Este sustantivo designa un encuentro o reunión entre personas, ya sea planificado o fortuito. En el uso neotestamentario podía significar salir al encuentro de alguien que llegaba, como cuando la gente salía de una ciudad para recibir a un dignatario que se acercaba. Los autores clásicos lo empleaban para encuentros casuales en el mercado o para reuniones formales. La palabra también podía significar controversia o debate confrontativo: encuentros donde chocaban posturas opuestas. En contextos astronómicos, se refería a la conjunción de cuerpos celestes. El sentido raíz de ''encuentro'' se adaptaba a diversos contextos donde los caminos se cruzaban, ya fueran pacíficos, contenciosos o celestiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4879', 'spa', 'Ser arrastrado juntamente, dejarse llevar con otros; ser influenciado o arrastrado por la presión de un grupo', 'Verbo compuesto en voz pasiva que significa ser llevado o arrastrado juntamente con otros, dejarse influenciar por la dinámica de grupo. Pablo lo usa tres veces: «no seáis altivos, sino condescended con los humildes» (Ro 12:16, traducción discutida), «hasta Bernabé fue arrastrado por la hipocresía de ellos» (Gá 2:13), y la advertencia contra «ser llevados por el error de los inicuos» (2 P 3:17). La palabra evoca el ser arrastrado por la corriente social: ceder ante la presión del grupo o dejarse influir por el mal ejemplo ajeno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4880', 'spa', 'Morir juntamente con, comorir; compartir la muerte con otro, ya sea literal o espiritualmente', 'Verbo compuesto que significa morir juntamente con alguien, compartir la muerte. Aparece tres veces: la declaración de Pedro «aunque tenga que morir contigo, no te negaré» (Mr 14:31), la afirmación de Pablo «estáis en nuestro corazón, para morir juntos y vivir juntos» (2 Co 7:3), y «si morimos con él, también viviremos con él» (2 Ti 2:11). Combina συν- («juntamente») con «morir», subrayando la muerte compartida, ya sea como martirio literal o como unión espiritual con la muerte de Cristo. La muerte compartida crea un destino compartido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4884', 'spa', 'Agarrar, arrebatar o arrastrar por la fuerza; se usa para asaltos demoníacos, violencia de turbas y embates de tormenta.', 'Verbo compuesto enérgico (σύν + ἁρπάζω) que significa apoderarse de alguien y llevárselo, arrebatar con violencia. Sus apariciones en el Nuevo Testamento abarcan tres ámbitos vívidos de captura violenta: un endemoniado repetidamente apresado por un espíritu inmundo (Lucas 8:29), opositores religiosos que arrastran a Esteban ante el Sanedrín (Hechos 6:12) y prenden a los compañeros de Pablo en Éfeso (Hechos 19:29), y un barco atrapado y empujado por la tormenta (Hechos 27:15). En cada caso, el sujeto es dominado por una fuerza que lo supera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4886', 'spa', 'Vínculo, ligamento; aquello que une, ya sea un tendón físico o una fuerza espiritual unificadora.', 'En el griego clásico, σύνδεσμος designaba cualquier sujeción que mantiene las cosas unidas: una articulación, un ligamento, un broche. Los escritores del Nuevo Testamento aprovecharon tanto la dimensión física como la metafórica. Pablo llama al amor el «vínculo de la perfección» (Col 3:14) y habla de los ligamentos del cuerpo que lo sostienen en unidad (Col 2:19). El uso más sombrío de Pedro en Hechos 8:23, «atadura de maldad», revela cómo la misma imagen de ligazón puede expresar cautividad al pecado. En español, «vínculo» y «ligamento» reflejan bien este doble registro de unión constructiva o sujeción opresiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4889', 'spa', 'Consiervo, compañero de servicio — uno que comparte el mismo amo y la misma obligación de servicio. Sustantivo compuesto que significa ''coesclavo'' o ''', 'Consiervo, compañero de servicio — uno que comparte el mismo amo y la misma obligación de servicio. Sustantivo compuesto que significa ''coesclavo'' o ''consiervo'', enfatizando la sujeción compartida a un amo común. En la parábola del siervo que no perdonó en Mateo, el σύνδουλος que debe una pequeña deuda suplica misericordia a aquel que fue perdonado de una suma enorme (Mateo 18:28–33), haciendo que el estatus compartido tenga un peso moral significativo. En Mateo 24:49, el siervo malvado golpea a sus consiervos. Pablo usa el término con afecto para Epafras (Colosenses 1:7) y Tíquico (Colosenses 4:7), enmarcando la colaboración apostólica como servicio conjunto a Cristo. En Apocalipsis, los ángeles se identifican a sí mismos como consiervos junto con los profetas (Apocalipsis 6:11; 19:10; 22:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4891', 'spa', 'Resucitar juntamente con, co-resucitar; levantar a alguien conjuntamente con otro, especialmente en resurrección espiritual', 'Verbo compuesto que significa resucitar juntamente con otro, co-resucitar. Pablo lo emplea tres veces: Dios «nos resucitó juntamente con Cristo» (Ef 2:6), «fuisteis resucitados juntamente con él mediante la fe» (Col 2:12), y «si habéis resucitado juntamente con Cristo...» (Col 3:1). Combina συν- («juntamente») con «levantar», enfatizando la resurrección compartida: los creyentes participan de la vida resucitada de Cristo. No se trata solo de una esperanza futura sino de una realidad presente: espiritualmente resucitados, sentados en los lugares celestiales, compartiendo ya su victoria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4892', 'spa', 'Concilio, Sanedrín — la asamblea judía de gobierno y justicia, tanto el cuerpo supremo en Jerusalén como los tribunales locales', 'Concilio, Sanedrín — la asamblea judía de gobierno y justicia, tanto el cuerpo supremo en Jerusalén como los tribunales locales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4893', 'spa', 'Conciencia — la facultad moral interna mediante la cual una persona evalúa su propia conducta como correcta o incorrecta', 'Conciencia — la facultad moral interna mediante la cual una persona evalúa su propia conducta como correcta o incorrecta');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4894', 'spa', 'Ser consciente de, percatarse conjuntamente; compartir un conocimiento o llegar a una comprensión.', 'Formado a partir de σύν («juntos») y οἶδα («saber»), este verbo expresa la idea de una conciencia compartida o interior: saber algo dentro de uno mismo, o saberlo en compañía de otro. En Hechos 5:2, Safira «sabía» del engaño que su marido llevó a cabo; en Hechos 12:12, Pedro «cayó en cuenta» de adónde había llegado. Pablo lo usa reflexivamente en 1 Corintios 4:4: «No soy consciente de nada contra mí mismo.» El verbo abarca desde la conciencia íntima de uno mismo hasta la comprensión repentina de una situación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4903', 'spa', 'Colaborar, trabajar conjuntamente con otro; cooperar o contribuir de manera conjunta a un esfuerzo común.', 'Formado por σύν (junto) y ἐργέω (trabajar), este verbo describe la labor conjunta hacia un propósito compartido. Su alcance en el NT es amplio: el Señor ''obraba con'' los apóstoles mediante señales confirmatorias (Mc 16:20), todas las cosas ''cooperan'' para bien bajo la soberanía de Dios (Ro 8:28), y la fe ''cooperaba'' con las obras de Abraham (Stg 2:22). Pablo también lo emplea para la colaboración humana en el ministerio (1 Co 16:16; 2 Co 6:1). En todos los casos, el verbo subraya la esencia cooperativa de la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4904', 'spa', 'Συνεργός es un término distintivamente paulino que aparece 13 veces en el Nuevo Testamento, casi exclusivamente en las cartas de Pablo, para describir', 'Συνεργός es un término distintivamente paulino que aparece 13 veces en el Nuevo Testamento, casi exclusivamente en las cartas de Pablo, para describir a quienes comparten la labor de proclamar el evangelio. Formado de σύν (''junto'') y ἔργον (''trabajo''), la palabra lleva un tono relacional cálido: no son meros empleados sino compañeros en una misión compartida. Pablo lo aplica a un notable elenco: Priscila y Aquila (Romanos 16:3), Timoteo (Romanos 16:21), Tito (2 Corintios 8:23), Epafrodito (Filipenses 2:25) y varios más. El término destaca la agencia conjunta y el propósito compartido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4905', 'spa', 'Reunirse, congregarse, juntarse; acompañar a alguien; eufemísticamente, unirse en relación conyugal', 'Reunirse, congregarse, juntarse; acompañar a alguien; eufemísticamente, unirse en relación conyugal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4906', 'spa', 'Comer junto con alguien; compartir la mesa como acto de comunión y aceptación social.', 'En el mundo mediterráneo antiguo, compartir la mesa era mucho más que consumir alimentos: constituía una declaración de aceptación social y comunión. Cada uso neotestamentario de este verbo lleva ese peso. Jesús ''come con'' publicanos y pecadores (Lc 15:2), escandalizando a los fariseos. Pedro comió con Cornelio y su casa (Hch 10:41), y luego fue criticado por comer con incircuncisos (Hch 11:3). Pablo prohíbe comer con un hermano impenitente (1 Co 5:11), y la retirada de Pedro de la mesa compartida con los gentiles provocó la crisis de Antioquía (Gá 2:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4907', 'spa', 'Entendimiento, discernimiento, agudeza mental; la facultad de captar significados con rapidez y discernir lo esencial.', 'Denota la capacidad de comprensión y discernimiento: no el mero conocimiento factual, sino la habilidad de percibir conexiones y captar un significado más profundo. Cuando el Jesús de doce años asombra a los maestros en el templo, Lucas emplea esta palabra para lo que los maravillaba: su σύνεσις, su perspicacia penetrante (Lc 2:47). Pablo ora para que los colosenses sean llenos de ella (Col 1:9), y en Mr 12:33 un escriba reconoce que amar a Dios con todo el ''entendimiento'' supera a los holocaustos. El español distingue matices con ''comprensión'', ''entendimiento'' e ''inteligencia'', reflejando la amplitud del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4908', 'spa', 'Inteligente, entendido, perspicaz; que posee discernimiento y buen juicio.', 'Derivado de συνίημι («comprender, juntar mentalmente»), συνετός describe a alguien capaz de sintetizar información para alcanzar entendimiento. Jesús da gracias al Padre por haber escondido estas cosas de «los sabios y entendidos» (Mt 11:25; Lc 10:21), usando el término casi irónicamente para aquellos cuya destreza intelectual se convierte en obstáculo. En Hechos 13:7, Sergio Paulo es llamado «hombre prudente», un elogio directo. Pablo cita el juicio de Isaías de que Dios «destruirá la inteligencia de los inteligentes» (1 Co 1:19), subrayando la insuficiencia de la sabiduría meramente humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4909', 'spa', 'συνευδοκέω — consentir, aprobar conjuntamente, expresar acuerdo con una acción o práctica.', 'Compuesto de σύν (''juntos'') y εὐδοκέω (''considerar bueno, aprobar''), συνευδοκέω significa unirse en la aprobación o dar el consentimiento a una acción o práctica. Aparece en contextos de gran peso moral a lo largo del Nuevo Testamento. Jesús acusa a los fariseos: ''ustedes son testigos y consienten en las obras de sus padres'' (Luke 11:48). Saulo de Tarso ''consentía en'' la ejecución de Esteban (Acts 8:1; 22:20). Pablo advierte que quienes ''aprueban'' la maldad comparten la culpa de quienes la practican (Rom 1:32). En una notable excepción pastoral, 1 Cor 7:12 lo usa positivamente: si un cónyuge no creyente ''consiente en vivir'' con un creyente, no deben divorciarse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4912', 'spa', 'Un verbo griego versátil que significa sujetar o apretar desde todos los lados, produciendo cuatro sentidos experienciales distintos en el Nuevo Testa', 'Un verbo griego versátil que significa sujetar o apretar desde todos los lados, produciendo cuatro sentidos experienciales distintos en el Nuevo Testamento. Pablo lo usa para la presión interior del amor de Cristo que le ''constriñe'' (2 Corintios 5:14) y la angustiosa presión de estar ''apretado entre'' dos deseos (Filipenses 1:23). En los relatos de sanación, describe ser preso de fiebre o enfermedad (Lucas 4:38; Mateo 4:24). Lucas lo emplea para multitudes que aprietan físicamente contra Jesús (Lucas 8:45) y para el asedio profetizado de Jerusalén (Lucas 19:43). Finalmente, cubre la sujeción física forzosa, como cuando los captores de Jesús lo ''sujetaban'' (Lucas 22:63) o la multitud ''tapó'' sus oídos contra Esteban (Hechos 7:57).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4914', 'spa', 'costumbre, hábito, práctica habitual; patrones establecidos de comportamiento o convenciones sociales', 'Sustantivo que designa una costumbre, hábito o práctica habitual, aquello que se ha vuelto rutinario por repetición o convención social. Aparece en la declaración de Pilato: «tenéis la costumbre de que os suelte un preso» (Juan 18:39), respecto a comer carne ofrecida a ídolos: «algunos, por la costumbre anterior con los ídolos» (1 Cor 8:7), y en la afirmación retórica de Pablo: «nosotros no tenemos tal costumbre» sobre el velo de las mujeres (1 Cor 11:16). En el griego clásico incluye asociación habitual, trato frecuente e incluso la conducta gregaria de animales, siempre enfatizando patrones repetidos y arraigados. La costumbre moldea poderosamente el comportamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4920', 'spa', 'entender, comprender, percibir — captar el significado o la importancia mediante discernimiento mental y espiritual', 'entender, comprender, percibir — captar el significado o la importancia mediante discernimiento mental y espiritual');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4921', 'spa', 'Recomendar o encomendar (a una persona); demostrar o probar (una cualidad); mantener unido o subsistir (como un todo unificado). El verbo griego συνίσ', 'Recomendar o encomendar (a una persona); demostrar o probar (una cualidad); mantener unido o subsistir (como un todo unificado). El verbo griego συνίστημι — literalmente ''estar juntos'' o ''poner juntos'' — se despliega en tres significados bellamente distintos en el Nuevo Testamento. Pablo lo usa con mayor frecuencia para recomendar o encomendar personas: ''Os recomiendo a nuestra hermana Febe'' (Ro 16:1), y rechaza a quienes ''se recomiendan a si mismos'' con cartas de recomendacion (2 Co 3:1). Pero συνίστημι tambien significa demostrar o probar: Dios ''demuestra su propio amor'' hacia nosotros en que Cristo murio por nosotros (Ro 5:8). El sentido mas grandioso aparece en Colosenses 1:17, donde Pablo declara que en Cristo ''todas las cosas subsisten'', la fuerza cosmica sustentadora que mantiene la creacion unida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4929', 'spa', 'ordenar, mandar, disponer; dar instrucciones o directivas, generalmente con autoridad', 'Verbo que significa ordenar, disponer o mandar, es decir, dar instrucciones o poner algo en orden. Mateo lo emplea tres veces: Jesús «ordenó» a los discípulos respecto al asno (21:6), les «mandó» preparar la Pascua (26:19), y Judas «dispuso» la compra del campo (27:10). En el uso clásico abarca desde formar ejércitos en línea de batalla hasta organizar elementos sistemáticamente o emitir mandatos. En Mateo, Jesús ejerce su autoridad mediante órdenes y disposiciones: mandando preparativos, dando instrucciones estratégicas y cumpliendo patrones proféticos incluso a través del precio de la traición de Judas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4930', 'spa', 'συντέλεια — consumación, culminación; especialmente el fin escatológico de la era presente.', 'Derivado de συντελέω (''llevar a término''), συντέλεια denota la consumación final o la conclusión definitiva de un período. En el Nuevo Testamento aparece casi exclusivamente en la frase escatológica συντέλεια τοῦ αἰῶνος (''la consumación del siglo''), concentrada en el Evangelio de Mateo. Los discípulos le preguntan a Jesús en el Monte de los Olivos: ''¿Cuál será la señal de tu venida y de la consumación del siglo?'' (Matt 24:3). Las parábolas de la cosecha en Matthew 13 explican que los ángeles separarán el trigo de la cizaña ''en la consumación del siglo'' (Matt 13:39-40, 49). La promesa final del Cristo resucitado sella el tema: ''Yo estoy con ustedes todos los días, hasta la consumación del siglo'' (Matt 28:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4931', 'spa', 'Llevar a cumplimiento, terminar; cumplirse o alcanzar su conclusión señalada; consumar o establecer (un pacto).', 'Synteleō combina syn- (''junto'') con teleō (''completar''), expresando la idea de reunir todas las partes hacia su fin previsto. Lucas lo emplea dos veces en la narración de las tentaciones: el diablo se apartó ''habiendo completado'' (syntelesas) toda tentación (Lucas 4:13), y al cumplirse los cuarenta días (syntelesthesisōn) sobrevino el hambre (Lucas 4:2). El uso profético-escatológico aparece en Marcos 13:4, donde los discípulos preguntan cuándo ''se cumplirán'' (synteleisthai) todas estas cosas. El sentido teológicamente más denso se halla en Hebreos 8:8, donde Dios declara ''consumaré'' (syntelesō) un nuevo pacto, no simplemente terminando una tarea, sino llevando a plena realización la promesa divina definitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4933', 'spa', 'guardar cuidadosamente, preservar, custodiar; proteger y conservar algo o a alguien con esmero', 'Verbo compuesto que significa guardar o preservar con cuidado, custodiar de cerca o atesorar. Aparece en la custodia protectora de Herodes sobre Juan el Bautista (Marcos 6:20), en María «atesorando» las palabras de Jesús en su corazón (Lucas 2:19), y en la parábola: «ambos se conservan» respecto al vino y los odres (Mateo 9:17). El prefijo συν- intensifica la preservación: sostener con cuidado, vigilar, proteger de pérdida o daño. En el griego clásico incluye mantener privilegios, observar leyes estrictamente, acechar oportunidades y resguardar bienes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4934', 'spa', 'Acordar conjuntamente, pactar; en voz media, llegar a una decisión o acuerdo mutuo, a menudo con tono conspirativo.', 'Este verbo compuesto (σύν + τίθημι, «poner juntos») significa convenir o pactar algo de manera conjunta. En el Nuevo Testamento predomina la voz media, dando el sentido de «acordaron entre sí». Los principales sacerdotes «acordaron» pagar a Judas (Lucas 22:5); los líderes judíos «habían acordado» expulsar a quien confesara a Cristo (Juan 9:22). En Hechos 23:20 los conspiradores «acordaron» un plan de asesinato, mientras que Hechos 24:9 emplea un compuesto afín para unirse a un ataque. El matiz recurrente es la toma colectiva de decisiones, frecuentemente teñida de intención hostil o secreta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4936', 'spa', 'correr juntos, confluir; acudir en masa o congregarse rápidamente en un mismo lugar', 'Verbo compuesto que significa correr juntos, precipitarse hacia el mismo lugar simultáneamente. Marcos describe a las multitudes «corriendo juntas» para adelantarse a encontrar a Jesús (6:33), a la gente «corriendo junta» hacia Pedro y Juan tras la sanación (Hechos 3:11), y Pedro asombrándose de que los gentiles no «corran juntamente» con los creyentes hacia el desenfreno (1 Pedro 4:4). En el uso clásico incluye confluir para la batalla, reunirse para un rescate y aglomerarse las multitudes. El prefijo συν- subraya la convergencia: múltiples personas precipitándose desde distintas direcciones hacia un mismo punto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4937', 'spa', 'Quebrar, quebrantar, destrozar; magullar: objetos destruidos o personas oprimidas y quebrantadas.', 'El verbo συντρίβω expresa la acción de romper o aplastar algo con fuerza, ya sea un objeto físico, un cuerpo humano o el espíritu de una persona. Abarca desde destrozar vasijas de barro en Apocalipsis 2:27 y quebrar un frasco de alabastro en Marcos 14:3, hasta la liberación espiritual de los quebrantados de corazón en Lucas 4:18, donde Jesús lee de Isaías en la sinagoga de Nazaret. La promesa de Pablo de que ''el Dios de paz aplastará a Satanás bajo vuestros pies'' (Romanos 16:20) evoca el protoevangelio de Génesis 3:15, otorgando a este verbo físico común un peso escatológico que resuena a lo largo de toda la narrativa bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4947', 'spa', 'Siria; la provincia romana al norte de Palestina, sede de Antioquía y Damasco, centro clave del cristianismo primitivo.', 'Nombre propio geográfico que designa la extensa provincia romana situada al norte de Palestina, con Antioquía como capital. En los Evangelios, Siria marca el alcance más lejano de la fama temprana de Jesús (Mt 4:24), mientras que en Hechos se convierte en la cuna del cristianismo gentil y la base desde la cual Pablo emprendió sus viajes misioneros. Lucas señala cuidadosamente que Cirenio gobernaba Siria cuando nació Jesús (Lc 2:2), anclando la narración en la historia imperial romana. Las glosas multilingües transliteran uniformemente el nombre, reflejando su condición de topónimo antiguo universalmente reconocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4951', 'spa', 'Arrastrar, tirar con fuerza por el suelo; llevar a rastras por la fuerza, ya sea personas, objetos o en sentido figurado.', 'Este verbo transmite fuerza física bruta: la acción de arrastrar o jalar algo o a alguien. Sus usos neotestamentarios pintan escenas vívidas: los discípulos arrastrando a tierra una red repleta de peces (Jn 21:8), Saulo arrastrando violentamente a creyentes fuera de sus casas para encarcelarlos (Hch 8:3), una turba arrastrando a Pablo fuera de la ciudad tras apedrearlo (Hch 14:19), y Jasón siendo arrastrado ante las autoridades (Hch 17:6). Apocalipsis 12:4 lo usa cósmicamente: la cola del dragón arrastra un tercio de las estrellas del cielo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4957', 'spa', 'Crucificar juntamente con; usado literalmente de la co-crucifixión y figuradamente de la unión del creyente con Cristo en su muerte.', 'Este verbo compuesto une σύν (juntamente con) y σταυρόω (crucificar), expresando una crucifixión compartida. Los Evangelios lo emplean literalmente para los criminales ejecutados junto a Jesús (Mt 27:44; Mc 15:32; Jn 19:32). Pablo lo transforma en una de sus metáforas teológicas más profundas: ''nuestro viejo hombre fue crucificado juntamente con él'' (Ro 6:6) y ''con Cristo estoy juntamente crucificado'' (Gá 2:20). La expresión española ''crucificado juntamente'' preserva la idea de participación conjunta que es central en la teología paulina de la muerte con Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4967', 'spa', 'matanza, degüello; muerte violenta, especialmente de víctimas sacrificiales o de quienes mueren bajo juicio', 'Sustantivo que designa matanza, degüello o muerte violenta, particularmente de animales sacrificiales o de quienes están condenados a morir. Aparece en el rollo del eunuco etíope: «como oveja fue llevada al matadero» (Hechos 8:32, citando Isaías 53:7), en Pablo citando «por causa de ti nos matan todo el día, somos contados como ovejas de matadero» (Romanos 8:36, del Salmo 44:22), y en Santiago condenando a los ricos: «habéis engordado vuestros corazones en día de matanza» (Santiago 5:5). La palabra evoca víctimas sacrificiales, gargantas cortadas, sangre derramada: inocencia destruida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4969', 'spa', 'Degollar, inmolar, matar violentamente — matar de forma violenta, especialmente cortando la garganta; usado para matanzas sacrificiales y homicidas. E', 'Degollar, inmolar, matar violentamente — matar de forma violenta, especialmente cortando la garganta; usado para matanzas sacrificiales y homicidas. El verbo σφάζω denota una muerte violenta, originalmente con el matiz específico de degüello o carnicería, aunque el NT lo extiende a cualquier matanza brutal. Caín ''degolló'' a Abel (1 Juan 3:12), usando el mismo verbo aplicado al Cordero ''inmolado desde la fundación del mundo'' (Apocalipsis 5:6, 9, 12; 13:8). Este emparejamiento léxico es teológicamente potente: el primer asesinato y el sacrificio supremo comparten la misma palabra. En Apocalipsis, el Cordero lleva las marcas de la inmolación pero se mantiene en pie, vivo, y a la espada del gran dragón rojo se le da autoridad para ''matar'' en la tierra (Apocalipsis 6:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4970', 'spa', 'En extremo, muchísimo, en gran manera — adverbio intensivo que amplifica la fuerza de verbos, adjetivos y emociones. El adverbio σφόδρα funciona como ', 'En extremo, muchísimo, en gran manera — adverbio intensivo que amplifica la fuerza de verbos, adjetivos y emociones. El adverbio σφόδρα funciona como intensificador con el significado de ''en extremo, muchísimo, en gran manera''. Especialmente en el Evangelio de Mateo, eleva el registro emocional de momentos clave: los magos se regocijaron ''en gran manera'' al ver la estrella (Mateo 2:10), los discípulos cayeron sobre sus rostros ''muy atemorizados'' en la Transfiguración (Mateo 17:6), se entristecieron ''en gran manera'' ante la predicción de la traición (Mateo 17:23; 26:22), y el centurión quedó ''muy atemorizado'' por el terremoto durante la crucifixión (Mateo 27:54). Otros usos incluyen la profunda angustia de los consiervos por el deudor que no perdonó (Mateo 18:31) y el asombro de los discípulos ante la enseñanza de Jesús sobre las riquezas (Mateo 19:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4972', 'spa', 'Un verbo que lleva el peso de las antiguas impresiones de sellos presionados sobre cera o arcilla. En el Nuevo Testamento, describe con mayor frecuenc', 'Un verbo que lleva el peso de las antiguas impresiones de sellos presionados sobre cera o arcilla. En el Nuevo Testamento, describe con mayor frecuencia el acto de Dios de marcar a los creyentes con el Espíritu Santo como sello de propiedad y autenticación (Efesios 1:13; 4:30; 2 Corintios 1:22). Pero también retiene el sentido concreto de cerrar algo físicamente: sellar la tumba de Cristo con una piedra (Mateo 27:66), sellar el abismo sobre Satanás (Apocalipsis 20:3), o sellar un rollo profético. Los dos sentidos se dividen claramente: marcar frente a cerrar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4973', 'spa', 'Sello o sigilo; dispositivo o su impresión usada para autenticar, asegurar o marcar propiedad, tanto en sentido literal como figurado. Σφραγίς designa', 'Sello o sigilo; dispositivo o su impresión usada para autenticar, asegurar o marcar propiedad, tanto en sentido literal como figurado. Σφραγίς designa tanto el dispositivo físico del sello (un anillo de sellar o estampilla) como la marca que deja. En el mundo antiguo, los sellos autenticaban documentos, aseguraban tumbas e indicaban propiedad. Pablo llama a la circuncisión de Abraham un sello de la justicia que tuvo por fe (Rom 4:11) y a los creyentes corintios el sello de su apostolado (1 Cor 9:2). El Apocalipsis da al término un protagonismo dramático: el rollo sellado con siete sellos solo puede ser abierto por el Cordero (Ap 5:1-9; 6:1-12). El fundamento firme de Dios lleva un sello de pertenencia divina (2 Tim 2:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4975', 'spa', 'casi, aproximadamente; que se acerca a un estado o cantidad sin alcanzarlo del todo', 'Adverbio que significa casi, aproximadamente o cerca de algo, indicando proximidad sin llegar a la totalidad. Lucas lo emplea al hablar de «casi toda la ciudad» reunida para escuchar a Pablo (Hch 13:44), Pablo afirma que «casi toda Asia» conoce su labor persuasiva (19:26), y Hebreos observa que «casi todo es purificado con sangre» bajo la ley (9:22). La palabra expresa cercanía a lo completo, reconociendo excepciones mientras subraya el patrón predominante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4977', 'spa', 'Rasgar, desgarrar, hender; verbo vívido de separación violenta, usado en los Evangelios para los momentos más dramáticos de la narrativa: los cielos r', 'Rasgar, desgarrar, hender; verbo vívido de separación violenta, usado en los Evangelios para los momentos más dramáticos de la narrativa: los cielos rasgándose en el bautismo de Jesús (Marcos 1:10), el velo del templo rompiéndose de arriba abajo en la crucifixión (Mateo 27:51; Marcos 15:38; Lucas 23:45), y rocas partiéndose. Jesús enseña que nadie arranca un pedazo de un vestido nuevo para remendar uno viejo (Lucas 5:36). En Hechos, la palabra se extiende metafóricamente a la fractura social: una ciudad dividida en opinión (Hechos 14:4) o una asamblea dividida en facciones rivales (Hechos 23:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4978', 'spa', 'Rotura, rasgadura (en tela); división, cisma o escisión (entre personas).', 'El sustantivo σχίσμα, del cual deriva el español ''cisma'', designa un desgarro o separación, aplicado tanto a objetos materiales como a comunidades humanas. Jesús emplea la imagen de una rasgadura en tela para advertir contra remendar un vestido viejo con tela sin encoger (Mt 9:16; Mr 2:21). Juan usa el término tres veces para divisiones sobre la identidad de Jesús (Jn 7:43; 9:16; 10:19). Pablo lo eleva a su registro teológico más intenso, instando a los corintios a que no haya divisiones entre ellos (1 Co 1:10; 11:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4980', 'spa', 'tener tiempo libre, estar desocupado; disponer de tiempo para dedicarse a algo', 'Verbo que significa tener tiempo libre, estar desocupado o dedicarse a algo por disponer de tiempo. Jesús describe cómo un espíritu inmundo encuentra su antigua casa «desocupada, barrida y adornada» (Mt 12:44; Lc 11:25), y Pablo aconseja a las parejas no privarse mutuamente «salvo de mutuo acuerdo por un tiempo, para dedicarse a la oración» (1 Co 7:5). El verbo abarca desde la simple vacuidad —una casa vacía vulnerable a la reocupación— hasta la dedicación intencionada de tiempo apartado para la vida espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4982', 'spa', 'Salvar, librar, rescatar o sanar; abarca la salvación espiritual, el rescate físico del peligro y la restauración a la salud o plenitud.', 'Uno de los verbos de mayor carga teológica en el Nuevo Testamento, σῴζω posee un rango semántico notable que va desde el rescate físico hasta la salvación eterna. En los Evangelios, Jesús lo emplea tanto para sacar a alguien de las olas (Mateo 8:25) como para pronunciar liberación espiritual (Mateo 1:21). La célebre declaración ''tu fe te ha salvado'' (Marcos 5:34; Lucas 7:50) se sitúa bellamente entre sanación y salvación, un matiz visible en cómo el árabe distingue entre jallaṣa (salvar/librar) y shafā (sanar/curar), mientras que el griego mantiene ambos significados en una sola palabra. El español alterna igualmente entre ''salvar'' y ''sanar'' según el contexto, revelando las fronteras de sentido que el griego deja fluidas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4983', 'spa', 'Cuerpo — el cuerpo humano físico; por extensión, la iglesia como cuerpo de Cristo y el cuerpo resucitado.', 'σῶμα es la palabra principal del Nuevo Testamento para el cuerpo físico, abarcando desde la instrucción de Jesús sobre ''el ojo como lámpara del cuerpo'' (Mateo 6:22) hasta la enseñanza de Pablo sobre la resurrección corporal (1 Corintios 15:35-44). A diferencia de σάρξ, que puede connotar fragilidad moral, σῶμα es teológicamente neutro o incluso positivo: el cuerpo es ''templo del Espíritu Santo'' (1 Corintios 6:19). La extensión más creativa de Pablo convierte a σῶμα en metáfora de la iglesia como cuerpo de Cristo, con miembros diversos que cumplen funciones distintas (1 Corintios 12:12-27; Efesios 4:4). Las 142 ocurrencias orbitan el concepto de un todo físico o comunitario organizado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4990', 'spa', 'Salvador, libertador — quien rescata del peligro o la destrucción; título tanto de Dios Padre como de Jesucristo', 'Salvador, libertador — quien rescata del peligro o la destrucción; título tanto de Dios Padre como de Jesucristo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4991', 'spa', 'Salvación, liberación — rescate del peligro o del pecado, el acto salvífico integral de Dios', 'Salvación, liberación — rescate del peligro o del pecado, el acto salvífico integral de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4992', 'spa', 'Salvífico, que trae salvación o liberación; como sustantivo, el medio o instrumento del acto salvífico de Dios.', 'Este adjetivo significa ''que trae salvación'' o ''salvífico'', y en el Nuevo Testamento aparece casi exclusivamente como sustantivo para referirse al poder salvador de Dios hecho visible. Simeón acuna al niño Jesús y declara: ''Mis ojos han visto tu salvación'' (Lucas 2:30). La profecía de Isaías de que ''toda carne verá la salvación de Dios'' resuena en Lucas 3:6 y Hechos 28:28. En Efesios 6:17 se convierte en el ''yelmo de la salvación'', y en Tito 2:11 la gracia de Dios se manifiesta como ''salvadora'' para todos los seres humanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4993', 'spa', 'Estar en su sano juicio, ser prudente y sobrio; abarca desde la cordura restaurada hasta la disciplina moral del pensamiento templado.', 'En el Nuevo Testamento, este verbo abarca dos ideas estrechamente relacionadas pero distinguibles: poseer una mente sana y racional, y ejercer un juicio sobrio y disciplinado. Cuando el endemoniado gadareno es hallado ''en su sano juicio'' (Marcos 5:15; Lucas 8:35), la palabra describe la restauración dramática de la cordura, un regreso del caos a la claridad. Pero Pablo y Pedro lo emplean para exhortar a los creyentes a un pensamiento disciplinado: no pensar de sí mismo más de lo que conviene (Romanos 12:3), y vivir con sobriedad lúcida ante la cercanía del fin (1 Pedro 4:7). La evidencia multilingüe confirma esta doble vertiente: cordura cognitiva y exhortación moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4997', 'spa', 'cordura, sensatez, dominio propio; equilibrio mental, moderación y pensamiento disciplinado', 'Sustantivo que denota cordura, dominio propio, sensatez o moderación: un estado mental equilibrado y disciplinado. Pablo declara «no estoy loco, sino que hablo palabras de verdad y de cordura» (Hch 26:25), instruye a las mujeres a adornarse con «sensatez» (1 Ti 2:9) y menciona el «dominio propio» entre las virtudes que las preservan (2:15). En el griego clásico abarca la cordura frente a la locura, la moderación en los deseos e incluso el gobierno prudente. El término engloba tanto la claridad racional como la disciplina moral: una mente ni frenética ni indulgente, sino equilibrada y contenida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4998', 'spa', 'Prudente, sobrio, templado; que ejerce dominio propio y juicio sensato sobre deseos e impulsos.', 'Literalmente «de mente sana» (de σῶς + φρήν), σώφρων describe a una persona cuyas facultades interiores están bien ordenadas y que practica una disciplina equilibrada. Las cuatro apariciones en el Nuevo Testamento se hallan en las Epístolas Pastorales, donde constituye un requisito clave para líderes eclesiales y creyentes maduros. El obispo debe ser σώφρων (1 Timoteo 3:2; Tito 1:8); los ancianos son exhortados a serlo (Tito 2:2); y las mujeres jóvenes son instruidas en esta virtud (Tito 2:5). El término abarca tanto la prudencia del juicio como la moderación de los apetitos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5007', 'spa', 'Originalmente denotando una balanza o par de platillos en el griego clásico, τάλαντον pasó a significar la unidad de peso estándar más pesada del anti', 'Originalmente denotando una balanza o par de platillos en el griego clásico, τάλαντον pasó a significar la unidad de peso estándar más pesada del antiguo Cercano Oriente, y por extensión una suma monetaria de enorme valor, aproximadamente 6.000 denarios o veinte años de salario de un jornalero común. En el Nuevo Testamento aparece exclusivamente en las parábolas de Jesús. El siervo que no perdona debe una suma absurdamente vasta de 10.000 talentos (Mateo 18:24), mientras que la parábola de los talentos distribuye cinco, dos y un talento a siervos según su capacidad (Mateo 25:15-28). El contexto parabólico le da una dimensión metafórica: los talentos representan dones, oportunidades o responsabilidades encomendadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5009', 'spa', 'Aposento, cuarto interior, despensa; un espacio cerrado apartado de la vista pública.', 'Ταμεῖον significaba originalmente un tesoro o almacén, pero en el período koiné se amplió para designar cualquier habitación interior privada. Jesús lo emplea de dos maneras contrastantes: en Mateo 6:6 es el aposento secreto donde uno se encuentra con Dios lejos de las miradas públicas, mientras que en Mateo 24:26 es la cámara oculta donde podrían acechar falsos mesías. Lucas 12:3 retoma ese sentido de ocultamiento — lo susurrado en cuartos interiores será proclamado desde los tejados. Lucas 12:24, en cambio, recupera el significado más antiguo de despensa o granero, al hablar de los cuervos que no tienen almacén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5010', 'spa', 'Orden, disposición; una sucesión establecida o un patrón fijo, especialmente de rango sacerdotal o institucional.', 'Τάξις transmite la idea de una disposición establecida o un orden designado. En el griego clásico abarcaba desde formaciones militares hasta rangos cívicos, pero el Nuevo Testamento concentra su uso en dos ámbitos principales: el orden sacerdotal litúrgico y el decoro congregacional. Zacarías sirve según el orden de su división sacerdotal (Lc 1:8), Pablo insiste en que todo en el culto se haga con decencia y orden (1 Co 14:40), y Hebreos identifica reiteradamente a Cristo como sacerdote ''según el orden de Melquisedec'' (Heb 5:6, 10; 6:20; 7:11, 17). El español ''orden'' preserva esta doble acepción de rango jerárquico y disposición apropiada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5011', 'spa', 'Humilde, de baja condición; de posición social modesta o disposición sencilla, usado a menudo de quienes Dios exalta.', 'Adjetivo que describe a alguien de baja condición social, de autovaloración modesta o socialmente insignificante. En el Magnificat, María celebra que Dios ha exaltado a los humildes (Lc 1:52), invirtiendo las jerarquías del mundo. Jesús mismo se declara ''manso y humilde de corazón'' (Mt 11:29), convirtiendo este término en un marcador cristológico. Pablo exhorta a los creyentes a no ser altivos sino a asociarse con los humildes (Ro 12:16), y Santiago promete que el ''hermano humilde'' será exaltado (Stg 1:9). El término abarca tanto la dimensión social como la espiritual de la humildad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5012', 'spa', 'Humildad, modestia de espíritu; la disposición de anteponer a otros, valorada en la ética del NT como virtud cristiana esencial.', 'En el griego clásico, ταπεινοφροσύνη tenía una connotación negativa de servilismo o mezquindad de ánimo, pero el Nuevo Testamento la transforma por completo en una virtud estimada. Pablo exhorta a los creyentes a adoptar la humildad en sus relaciones (Ef 4:2; Fil 2:3), tomando como modelo la actitud de autovaciamiento de Cristo mismo. En Colosenses 2:18, Pablo advierte contra una versión falsificada: una humildad fingida ligada al culto a los ángeles, mostrando que incluso esta virtud puede ser distorsionada. La verdadera humildad cristiana no es debilidad, sino fortaleza que se inclina voluntariamente al servicio del prójimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5013', 'spa', 'Ταπεινόω abarca todo el arco de la inversión bíblica: lo que se eleva será derribado, y lo que se inclina será levantado. La paradoja repetida de Jesú', 'Ταπεινόω abarca todo el arco de la inversión bíblica: lo que se eleva será derribado, y lo que se inclina será levantado. La paradoja repetida de Jesús, ''el que se humilla será exaltado, y el que se exalta será humillado'' (Mateo 23:12; Lucas 14:11; 18:14), usa tanto la voz activa como la pasiva de este mismo verbo para expresar la economía divina de inversión. Pablo afirma haberse ''humillado'' predicando el evangelio gratuitamente (2 Corintios 11:7; 12:21), y Filipenses 2:8 declara que Cristo ''se humilló a sí mismo, haciéndose obediente hasta la muerte''. Santiago y Pedro emiten el imperativo: ''Humillaos delante del Señor'' (Santiago 4:10; 1 Pedro 5:6), no como degradación, sino como la postura que precede a la exaltación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5014', 'spa', 'Humillación, bajeza, condición humilde; el estado de ser rebajado o vivir en circunstancias modestas.', 'Ταπείνωσις denota el estado o experiencia de hallarse en una posición baja — ya sea social, física o espiritual. El Magnificat de María celebra que Dios miró su «humilde condición» (Lucas 1:48), convirtiendo la humildad en ocasión de favor divino. En Hechos 8:33, el término aparece en el cántico del Siervo de Isaías citado por Felipe: la «humillación» de Cristo incluyó la negación de justicia. Filipenses 3:21 contrasta nuestro «cuerpo de humillación» con el cuerpo glorioso de Cristo, y Santiago 1:10 advierte al rico que su exaltación se marchitará en bajeza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5015', 'spa', 'Turbar, agitar o sumir en conmoción; del corazón, de comunidades o del agua removida físicamente. Ταράσσω abarca todo el espectro de la perturbación, ', 'Turbar, agitar o sumir en conmoción; del corazón, de comunidades o del agua removida físicamente. Ταράσσω abarca todo el espectro de la perturbación, desde el temblor de un corazón asustado hasta la conmoción de una ciudad entera. Cuando Herodes oyó del rey recién nacido, «se turbó, y toda Jerusalén con él» (Mt 2:3). Jesús mismo usa la palabra para consolar a sus discípulos: «No se turbe vuestro corazón» (Jn 14:1,27). En Hechos, describe el caos social causado por falsos maestros que «perturban» a los creyentes (Hch 15:24; Gál 1:7; 5:10). En su sentido más concreto, retrata la agitación física del estanque de Betesda (Jn 5:4,7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5019', 'spa', 'Tarso, ciudad destacada de Cilicia (sureste de Asia Menor), conocida como lugar de nacimiento de Pablo', 'Tarso era un importante centro cultural y comercial en la provincia romana de Cilicia, ubicado en lo que hoy es el sur de Turquía. La ciudad era célebre por su universidad y sus escuelas filosóficas, rivalizando con Atenas y Alejandría. Pablo se identifica como ciudadano de esta «ciudad no insignificante» (Hch 21:39), destacando tanto su formación griega como su ciudadanía romana. El nombre aparece en contextos que señalan los orígenes de Pablo y sus desplazamientos durante los inicios de su ministerio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5021', 'spa', 'Disponer, designar, asignar a un puesto o tarea; en voz media, dedicarse voluntariamente a un servicio.', 'Enraizado en el lenguaje militar de organizar tropas en formación, este verbo lleva al Nuevo Testamento el sentido más amplio de colocar a alguien o algo en un orden establecido. Un centurión se describe a sí mismo como ''puesto bajo autoridad'' (Mt 8:9; Lc 7:8), y el concilio de Jerusalén ''designó'' delegados (Hch 15:2). La voz media produce un matiz reflexivo: la familia de Estéfanas ''se dedicó'' al servicio de los santos (1 Co 16:15). El peso teológico aparece en Hechos 13:48, donde los ''ordenados'' para vida eterna creyeron.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5022', 'spa', 'Toro, buey; un bovino macho adulto, especialmente como animal de sacrificio.', 'Ταῦρος es la palabra griega estándar para designar al toro, con profundas resonancias tanto en los sistemas sacrificiales paganos como bíblicos. En Mateo 22:4, el banquete de un rey presenta toros y animales cebados sacrificados — imagen de celebración suntuosa. Hechos 14:13 registra al sacerdote de Zeus trayendo toros para sacrificar a Pablo y Bernabé, una dramática colisión entre el culto pagano y la misión apostólica. Hebreos 9:13 y 10:4 invocan el sistema sacrificial levítico: la sangre de toros y machos cabríos jamás puede quitar verdaderamente el pecado, preparando así el argumento de la superioridad de la ofrenda única de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5024', 'spa', 'esta, estas (formas femeninas); pronombre demostrativo que señala personas o cosas cercanas', 'Estas son las formas femeninas del pronombre demostrativo común οὗτος, que significa ''esta'' o ''estas''. El griego distinguía cuidadosamente género, número y caso en los demostrativos, de modo que αὕτη (nominativo femenino singular), ταύτης (genitivo femenino singular) y formas afines señalaban específicamente sustantivos femeninos. El demostrativo surgió de la reduplicación del artículo con una -υ- intercalada, creando un fuerte indicador deíctico de algo presente o recién mencionado. En el discurso, marcaba elementos cercanos físicamente o referidos poco antes. Los escritores bíblicos lo usaron constantemente para referirse a mujeres, ciudades, conceptos o sustantivos abstractos femeninos mencionados previamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5025', 'spa', 'estas (femenino plural dativo/genitivo); formas femeninas de ''estas'' en casos oblicuos', 'Estas son formas femeninas plurales en dativo y genitivo del demostrativo οὗτος: ταύταις (dativo plural, ''a/para estas'') y τούτων (genitivo plural, ''de estas''). El elaborado sistema de casos del griego requería formas distintas para cada combinación de género, número y función gramatical. El dativo indicaba objetos indirectos o medio (''por medio de estas cosas''), mientras que el genitivo marcaba posesión o relación (''de estas mujeres''). Los escritores bíblicos empleaban estas formas para mantener una referencia clara a sustantivos femeninos plurales mencionados anteriormente en el discurso, asegurando que los lectores pudieran rastrear qué entidades se estaban discutiendo incluso en oraciones complejas con múltiples referentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5026', 'spa', 'esta (femenino singular); formas oblicuas del demostrativo femenino singular en dativo, genitivo y acusativo', 'Estas son las formas de caso oblicuo del demostrativo femenino singular: ταύτῃ (dativo, ''a/para esta''), ταύτης (genitivo, ''de esta'') y ταύτην (acusativo, ''esta'' como objeto directo). Cada forma cumplía funciones gramaticales específicas manteniendo la referencia a un sustantivo femenino singular. El dativo señalaba objetos indirectos, ubicación o medio; el genitivo indicaba posesión o relación; el acusativo marcaba objetos directos. En la narrativa y el discurso bíblico, estas formas eran esenciales para mantener la coherencia referencial entre cláusulas y oraciones, permitiendo a los autores señalar de vuelta a sustantivos femeninos —mujeres, ciudades, conceptos— sin repetir el sustantivo mismo, logrando una prosa griega más elegante y eficiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5028', 'spa', 'Tumba, sepulcro, lugar de sepultura; una cámara excavada en la roca donde se depositan los muertos.', 'Se refiere a un lugar de sepultura, normalmente una cámara tallada en la roca, donde se deposita un cuerpo tras la muerte. En los Evangelios aparece de forma prominente en la narrativa de la Pasión para designar la tumba de Jesús: el sepulcro nuevo donde José de Arimatea deposita el cuerpo (Mt 27:61), sellado con una piedra y custodiado por soldados (Mt 27:64, 66). Jesús también emplea la palabra en su crítica profética a los escribas y fariseos, llamándolos ''sepulcros blanqueados'': hermosos por fuera pero llenos de huesos de muertos por dentro (Mt 23:27, 29).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5030', 'spa', 'Rápidamente, apresuradamente, pronto — adverbio de rapidez temporal que expresa urgencia o advierte contra la precipitación. El adverbio ταχέως (tache', 'Rápidamente, apresuradamente, pronto — adverbio de rapidez temporal que expresa urgencia o advierte contra la precipitación. El adverbio ταχέως (tacheos) significa ''rápidamente'', ''con prontitud'' o ''pronto'', y conlleva tanto un sentido positivo de urgencia como uno de advertencia contra la precipitación, según el contexto. Cuando Jesús ordena al siervo salir ''pronto'' a las calles (Lucas 14:21), la palabra transmite urgencia divina. Pero cuando Pablo se asombra de que los gálatas estén abandonando ''tan pronto'' el evangelio (Gálatas 1:6), la rapidez resulta alarmante. Igualmente, Pablo advierte a Timoteo que no imponga las manos a nadie ''con ligereza'' (1 Timoteo 5:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5032', 'spa', 'Más rápidamente, más pronto; adverbio comparativo que expresa mayor velocidad o urgencia.', 'Forma comparativa de ταχύς (''veloz''), τάχιον significa ''más rápidamente'' o ''más pronto''. Jesús dice a Judas en la Última Cena: «Lo que vas a hacer, hazlo más pronto» (Juan 13:27), acelerando los acontecimientos con intensidad sobrecogedora. En Juan 20:4, el discípulo amado corre más rápido que Pedro y llega primero al sepulcro. El autor de Hebreos lo emplea con urgencia esperanzada: ora para que «sea restituido a vosotros más pronto» (Heb 13:19), y anuncia la liberación de Timoteo para visitarlos «más rápidamente» (Heb 13:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5034', 'spa', 'Rapidez, premura, prontitud; casi siempre en la frase dativa ''ἐν τάχει'' que significa ''pronto'' o ''sin demora''.', 'Sustantivo que denota celeridad o premura, empleado en el Nuevo Testamento casi exclusivamente en la frase adverbial ''ἐν τάχει'' —''con prontitud, pronto, sin demora''. La expresión transmite urgencia: Dios hará justicia con rapidez (Lc 18:8), el ángel ordena a Pedro que se levante presto (Hch 12:7), y Pablo promete que Dios aplastará a Satanás bajo los pies de los creyentes en breve (Ro 16:20). El matiz es más de inminencia temporal que de mera velocidad física, como bien refleja la voz española ''brevedad''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5035', 'spa', 'El adverbio ταχύ (''rápidamente'') transmite velocidad, prontitud o urgencia en la acción. Aparece en diversos contextos del Nuevo Testamento. Jesús ins', 'El adverbio ταχύ (''rápidamente'') transmite velocidad, prontitud o urgencia en la acción. Aparece en diversos contextos del Nuevo Testamento. Jesús insta a una reconciliación rápida: ''ponte de acuerdo pronto con tu adversario'' (Mateo 5:25). El ángel en el sepulcro ordena a las mujeres ''id pronto y decid a sus discípulos'' (Mateo 28:7-8). En la parábola del gran banquete, el señor ordena a su siervo ''sal pronto por las calles'' (Lucas 14:21). El Evangelio de Juan lo usa con aguda economía narrativa: Judas sale de la última cena después de que Jesús dice ''lo que vas a hacer, hazlo pronto'' (Juan 13:27). El Apocalipsis cierra con la promesa ''vengo pronto'' (Apocalipsis 2:16; 11:14; 22:7, 12, 20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5037', 'spa', 'Y, tanto... como, también — conjunción enclítica que enlaza palabras, frases o cláusulas.', 'La partícula τε es una de las herramientas conectivas más sutiles del griego, funcionando como conjunción enclítica que une elementos con mayor estrechez que el común καί. Aparece frecuentemente en la construcción pareada τε...καί (''tanto... como''), confiriendo un sentido de emparejamiento natural o pertenencia lógica. Lucas y el autor de Hebreos la emplean con notable frecuencia, otorgando a Hechos y Hebreos un registro marcadamente literario. El español la reduce a la simple conjunción ''y,'' al igual que el francés ''et'' y el alemán ''und,'' aunque estas traducciones pierden el matiz de la posición enclítica que señala un vínculo lógico más estrecho entre los elementos unidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5038', 'spa', 'Muralla o muro de ciudad; estructura defensiva grande que rodea y protege un asentamiento urbano.', 'Τεῖχος designa específicamente una gran muralla defensiva que circunda una ciudad, a diferencia de τοῖχος (G5109), que se refiere a la pared interior de un edificio. En el Nuevo Testamento sus apariciones se reparten entre narración histórica y visión apocalíptica. Pablo escapa de Damasco al ser descolgado por una abertura en la muralla (Hch 9:25; 2 Co 11:33), los muros de Jericó caen por la fe (Heb 11:30), y la Jerusalén celestial se describe con una muralla grande y alta provista de doce puertas y doce cimientos (Ap 21:12-19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5040', 'spa', 'Hijitos; diminutivo afectuoso usado por Jesús y el apóstol Juan para dirigirse a los discípulos o creyentes.', 'Diminutivo tierno de τέκνον (hijo), empleado como una expresión cálida de cercanía hacia los dependientes espirituales. Jesús lo usa una sola vez en la Última Cena: ''Hijitos, un poco más estaré con vosotros'' (Jn 13:33). El apóstol Juan lo adopta como su modo característico de dirigirse a los creyentes a lo largo de 1 Juan, escribiendo ''hijitos'' al exhortarlos a caminar en justicia y amor. El español ''hijitos'' conserva bien la fuerza afectiva del diminutivo que distingue esta palabra del más neutro τέκνα.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5043', 'spa', 'Hijo o descendiente, ya sea biológico, espiritual, o como vocativo afectuoso dirigido a una persona más joven.', 'Término rico para hijo o descendiente, enraizado en el verbo τίκτω (''dar a luz''), τέκνον porta un peso tanto biológico como relacional. En los Evangelios describe hijos y descendientes literales (Mateo 2:18; 3:9), mientras que Pablo lo extiende poderosamente a los hijos espirituales de la fe (Gálatas 4:28). Como vocativo se convierte en un tratamiento íntimo — Jesús dice ''τέκνον'' al paralítico (Marcos 2:5) y a sus discípulos (Marcos 10:24), transmitiendo ternura paternal. La evidencia multilingüe es consistente: el español ''hijos,'' el francés ''enfant'' y el alemán ''Kinder'' siguen el sentido biológico, mientras que el uso vocativo se distingue en pasajes donde el trato directo conlleva calidez emocional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5046', 'spa', 'Perfecto, completo, maduro: que ha alcanzado la meta o fin previsto; plenamente desarrollado en carácter o cualidad. Enraizado en τέλος («fin, meta»),', 'Perfecto, completo, maduro: que ha alcanzado la meta o fin previsto; plenamente desarrollado en carácter o cualidad. Enraizado en τέλος («fin, meta»), τέλειος describe lo que ha llegado a su plenitud prevista. Cuando Jesús dice «sed perfectos como vuestro Padre celestial es perfecto» (Mt 5:48), el llamado no es a un desempeño impecable sino a una integridad de carácter: el amor extendido incluso a los enemigos. Pablo lo usa para creyentes maduros que captan una sabiduría más profunda (1 Cor 2:6) y lo contrasta con lo parcial e infantil (1 Cor 13:10). Santiago igualmente lo vincula a la perseverancia que produce plenitud (Stg 1:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5048', 'spa', 'Perfeccionar o llevar a plenitud; perfeccionar personas espiritualmente, o concluir una tarea o propósito', 'Perfeccionar o llevar a plenitud; perfeccionar personas espiritualmente, o concluir una tarea o propósito');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5053', 'spa', 'Τελευτάω deriva de τέλος (''fin'') y en el griego clásico podía significar ''llevar a cumplimiento'' o ''completar''. Sin embargo, en el período koiné, el s', 'Τελευτάω deriva de τέλος (''fin'') y en el griego clásico podía significar ''llevar a cumplimiento'' o ''completar''. Sin embargo, en el período koiné, el significado se había estrechado casi por completo a ''morir'': llegar al final de la propia vida. Las 13 apariciones en el Nuevo Testamento llevan este significado sin excepción. El verbo aparece en pronunciamientos legales (Mateo 15:4, ''que muera'', citando el Decálogo), fórmulas narrativas de sucesión (Mateo 2:19, ''cuando murió Herodes''), y los casos de prueba de los saduceos sobre el matrimonio por levirato (Mateo 22:25; Marcos 12:20-22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5055', 'spa', 'Completar, terminar o llevar a su fin; cumplir profecía u obligación; pagar impuestos o tributo', 'Completar, terminar o llevar a su fin; cumplir profecía u obligación; pagar impuestos o tributo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5056', 'spa', 'Fin, conclusión, terminación (esp. escatológica); impuesto, tributo o derecho aduanero; meta, resultado o propósito', 'Fin, conclusión, terminación (esp. escatológica); impuesto, tributo o derecho aduanero; meta, resultado o propósito');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5057', 'spa', 'Cobrador de impuestos, publicano; agente despreciado que recaudaba peajes y tributos para Roma.', 'Cobrador de impuestos, publicano; agente despreciado que recaudaba peajes y tributos para Roma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5058', 'spa', 'mesa de cobro, oficina de impuestos; lugar donde los recaudadores se sentaban a cobrar tributos y aranceles', 'La mesa de cobro era el puesto físico donde los recaudadores de impuestos ejercían su oficio, situado por lo general en las puertas de la ciudad, caminos de peaje o puertos. En la Judea del siglo I, estos puestos simbolizaban la colaboración con la ocupación romana, lo que hacía de los publicanos figuras despreciadas. Las tres apariciones neotestamentarias describen el momento en que Jesús llama a un recaudador al discipulado, un acto escandaloso que mostraba su misión hacia los pecadores y no hacia los justos. La mesa de cobro se convierte así en escenario vívido de la gracia radical.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5059', 'spa', 'Prodigio, portento o señal milagrosa; una maravilla sobrenatural que suscita asombro y apunta al poder divino. Τέρας se refiere a un acontecimiento ex', 'Prodigio, portento o señal milagrosa; una maravilla sobrenatural que suscita asombro y apunta al poder divino. Τέρας se refiere a un acontecimiento extraordinario que inspira asombro y señala actividad divina. En el NT aparece casi exclusivamente en la frase pareada σημεῖα καὶ τέρατα («señales y prodigios»), donde σημεῖον enfatiza el significado revelador y τέρας la dimensión asombrosa del mismo acto poderoso. El sermón de Pedro en Pentecostés declara que Dios acreditó a Jesús mediante prodigios (Hch 2:22), y la profecía de Joel anuncia portentos cósmicos (Hch 2:19). Jesús mismo advierte que falsos mesías realizarán señales y prodigios para engañar (Mt 24:24; Mc 13:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5062', 'spa', 'Cuarenta; número cardinal empleado para períodos de prueba, peregrinación y preparación divina en las Escrituras.', 'Cuarenta; número cardinal empleado para períodos de prueba, peregrinación y preparación divina en las Escrituras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5064', 'spa', 'Cuatro — el numeral cardinal cuatro, usado como adjetivo que modifica sustantivos en todos los casos y géneros', 'Cuatro — el numeral cardinal cuatro, usado como adjetivo que modifica sustantivos en todos los casos y géneros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5067', 'spa', 'Cuarto — número ordinal que indica la cuarta posición en una secuencia, o una cuarta parte (un cuarto). El ordinal griego estándar para ''cuarto'', usad', 'Cuarto — número ordinal que indica la cuarta posición en una secuencia, o una cuarta parte (un cuarto). El ordinal griego estándar para ''cuarto'', usado en el Nuevo Testamento para marcar secuencia: la cuarta vigilia de la noche (Mateo 14:25; Marcos 6:48), la cuarta criatura viviente (Apocalipsis 4:7) y el cuarto sello (Apocalipsis 6:7). En Apocalipsis 6:8, al caballo pálido se le da autoridad ''sobre la cuarta parte de la tierra'', donde la palabra pasa del sentido ordinal puro al de cantidad fraccionaria. El español refleja bien esta distinción: ''cuarto'' para los usos ordinales y ''cuarta parte'' para el sentido fraccionario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5070', 'spa', 'Cuatro mil; número cardinal usado en los relatos de alimentación milagrosa y en una referencia histórica en Hechos.', 'Este adjetivo numeral significa simplemente ''cuatro mil''. Aparece principalmente en la alimentación de los cuatro mil, donde Jesús alimenta milagrosamente a una multitud de ese tamaño (Mateo 15:38; Marcos 8:9), y en el recuerdo posterior que los discípulos hacen de aquel evento (Mateo 16:10; Marcos 8:20). Hechos 21:38 conserva un uso diferente, donde un comandante romano pregunta a Pablo si es el egipcio que condujo a cuatro mil sicarios al desierto. En todas las lenguas se traduce como un simple numeral: ''cuatro mil'' en español, ''quatre mille'' en francés, ''viertausend'' en alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5071', 'spa', 'Cuatrocientos; número cardinal 400, empleado en referencias históricas y cronológicas.', 'Τετρακόσιοι (''cuatrocientos'') aparece exclusivamente en recuentos históricos dentro de Hechos y Gálatas. En Hechos 5:36, Gamaliel recuerda a un rebelde que reunió unos cuatrocientos seguidores antes de ser dispersados. Hechos 7:6 cita la profecía de Dios a Abraham sobre cuatrocientos años de esclavitud, y Hechos 13:20 menciona aproximadamente cuatrocientos cincuenta años de jueces. Pablo fundamenta su argumento sobre la prioridad de la promesa abrahámica en Gálatas 3:17, señalando que la ley vino cuatrocientos treinta años después. Cada aparición ancla un punto teológico o retórico en una duración histórica concreta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5074', 'spa', 'Cuadrúpedo; que tiene cuatro patas, referente a animales terrestres que caminan sobre cuatro extremidades', 'Este adjetivo describe la categoría de animales de cuatro patas, distinguiéndolos de las aves, los peces y los reptiles en la clasificación bíblica de los seres vivos. El término aparece en contextos que enumeran diversas clases de criaturas, ya sea en visiones (Hechos 10 y 11) o en descripciones de la idolatría humana (Romanos 1). La filosofía natural antigua empleaba comúnmente el número de patas como sistema primario de clasificación de los seres vivos, lo que convierte a este término en un descriptor directo que abarca desde el ganado hasta las fieras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5075', 'spa', 'Ser tetrarca, gobernar como tetrarca (gobernador de la cuarta parte de una región)', 'Originalmente un tetrarca gobernaba la cuarta parte de un territorio, aunque para la época del Nuevo Testamento el título se había convertido en una designación general para un gobernante subordinado bajo la autoridad romana, un escalón por debajo de un rey pleno en la jerarquía de gobernantes clientelares. El verbo aparece únicamente en Lucas 3:1, donde sitúa el ministerio de Jesús en un contexto histórico preciso al nombrar a los gobernantes políticos de diversas regiones —Herodes, Felipe y Lisanias— cada uno gobernando sus respectivos territorios como tetrarcas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5076', 'spa', 'Tetrarca; gobernante regional bajo autoridad romana, de rango inferior a rey, que regía la cuarta parte de un territorio.', 'Derivado del griego ''gobernante de una cuarta parte'', este título designaba a un gobernador provincial bajo autoridad romana con rango inferior al de rey. En el Nuevo Testamento se refiere exclusivamente a gobernantes de Palestina, sobre todo Herodes Antipas. El español ''tetrarca'' y el francés ''tétrarque'' conservan la forma griega prácticamente intacta, lo cual refleja cómo este título político técnico pasó directamente a las lenguas occidentales. Lucas 3:19 y Hechos 13:1 aplican el término a figuras históricas concretas del sistema de estados vasallos romanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5078', 'spa', 'Arte, oficio, profesión, destreza; la habilidad aprendida o el oficio con el que uno se gana la vida', 'En el uso antiguo, τέχνη abarcaba tanto la habilidad técnica requerida para un oficio como la profesión en sí misma, desde la metalurgia hasta la construcción naval o la adivinación. La palabra podía tener connotaciones negativas (astucia, artificios) o positivas (maestría artística). En el Nuevo Testamento aparece en referencias directas a oficios y profesiones honestas. Curiosamente, es la raíz de nuestra palabra «técnica» y «tecnología», aunque el concepto antiguo era mucho más personal y artesanal que nuestra concepción moderna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5079', 'spa', 'Artesano, artífice o diseñador experto; persona con pericia técnica para construir o dar forma a materiales.', 'Designa a una persona hábil en un oficio o arte, desde la metalurgia hasta la arquitectura. En Hechos 19:24 y 19:38 describe a los plateros de Éfeso cuyo sustento dependía de fabricar santuarios de Artemisa. Hebreos 11:10 eleva el término de manera notable al llamar a Dios τεχνίτης y arquitecto de la ciudad celestial, un uso que revela el alcance teológico de la palabra. Apocalipsis 18:22 lamenta el silenciamiento de todo artesano en la Babilonia caída, evocando la desolación total de la actividad humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5082', 'spa', 'Tan grande, tan poderoso, tan enorme; pronombre demostrativo enfático que resalta un grado o magnitud extraordinarios.', 'Demostrativo intensificador que llama la atención sobre la escala o gravedad extraordinaria de algo. En 2 Corintios 1:10, Pablo habla de liberación de «tan grande» peligro de muerte, mientras que Hebreos 2:3 advierte contra descuidar «tan grande» salvación. Santiago 3:4 se maravilla de que navíos «tan grandes» sean gobernados por un pequeño timón, y Apocalipsis 16:18 describe un terremoto «tan grande» como nunca se había visto. En cada caso, el término eleva al sustantivo que modifica más allá de lo ordinario, marcando una magnitud que exige atención.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5083', 'spa', 'Vigilar, guardar, observar o cumplir; desde obedecer mandamientos hasta proteger personas o reservar cosas para el futuro.', 'En el Nuevo Testamento, τηρέω abarca un rico campo semántico centrado en la idea de atención vigilante. Con mayor frecuencia describe la observancia fiel de mandamientos y enseñanzas: cuando Jesús dice «si me amáis, guardad mis mandamientos» (Juan 14:15), la palabra no transmite obediencia forzada sino devoción atenta. El hindi मानना (''obedecer'') y el árabe حفظ (''preservar, observar'') captan bien este sentido. El verbo se extiende también a la protección de personas contra el peligro, como cuando Jesús ora para que el Padre «guarde» a sus discípulos (Juan 17:11). En algunos pasajes, especialmente en las epístolas petrinas, describe algo reservado para un propósito futuro: una herencia «guardada en los cielos» (1 Pe 1:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5084', 'spa', 'Custodia, prisión, observancia; lugar o estado de ser guardado, retenido o custodiado', 'Este término posee sentidos tanto concretos como abstractos: custodia física (un lugar seguro como la prisión) y el acto de guardar u observar algo. En el griego secular podía significar la custodia de bienes, la preservación de la salud o la observancia de leyes. El Nuevo Testamento lo emplea principalmente para el encarcelamiento literal, aunque 1 Corintios 7:19 lo extiende a la observancia de los mandamientos de Dios, mostrando cómo la restricción física y la disciplina espiritual comparten la misma raíz semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5085', 'spa', 'Tiberias, ciudad en la orilla occidental del mar de Galilea, nombrada en honor al emperador Tiberio', 'Fundada alrededor del año 20 d.C. por Herodes Antipas y nombrada en honor al emperador romano, Tiberias se convirtió en una de las principales ciudades junto al mar de Galilea. Construida sobre un cementerio, era considerada impura por los judíos observantes, lo cual podría explicar por qué Jesús aparentemente nunca la visitó a pesar de su extenso ministerio galileo. El lago mismo llegó a llamarse mar de Tiberias (Juan 6:1; 21:1), reflejo de la prominencia de la ciudad. Hoy sigue siendo una ciudad importante en el norte de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5087', 'spa', 'Poner, colocar o depositar algo; por extensión, designar para un cargo, dar la vida sacrificialmente o resolver en el corazón.', 'En su núcleo, τίθημι significa poner o colocar algo en una posición — una lámpara sobre un candelero, un cuerpo en un sepulcro, enemigos debajo de los pies. Pero esta acción física se ramifica en un rico territorio metafórico. Cuando Dios ''coloca'' a alguien en un cargo, la palabra se convierte en ''designar'' o ''establecer'' (Hechos 20:28; 1 Timoteo 1:12). De modo más llamativo, Jesús usa τίθημι τὴν ψυχήν — literalmente ''pongo mi vida'' — para el acto voluntario de entregar su vida (Juan 10:11-18), una expresión tan distintiva que el coreano pasa del ordinario 놓다 a 내놓다 (soltar, entregar), captando el matiz sacrificial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5088', 'spa', 'Dar a luz, parir; en voz pasiva, nacer; por extensión, producir o dar fruto. Τίκτω es el verbo griego fundamental para el acto de dar a luz. Aparece e', 'Dar a luz, parir; en voz pasiva, nacer; por extensión, producir o dar fruto. Τίκτω es el verbo griego fundamental para el acto de dar a luz. Aparece en los momentos más decisivos de la narrativa neotestamentaria: el ángel dice a José que María «dará a luz un hijo» (Mt 1:21), Elisabet da a luz a Juan (Lc 1:57), y la mujer celestial de Apocalipsis da a luz un hijo que gobernará las naciones (Ap 12:2,4). En su forma pasiva marca el nacimiento de Jesús como «el que ha nacido Rey de los judíos» (Mt 2:2) y el Salvador anunciado a los pastores (Lc 2:11). Hebreos 6:7 extiende la imagen a la tierra que produce vegetación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5089', 'spa', 'Arrancar, desprender; específicamente arrancar espigas de grano o arrancarse el cabello', 'Este verbo describe la acción de arrancar o desprender algo con la mano, ya sea cabello (en señal de duelo o angustia) o espigas de grano (para comer). En el Nuevo Testamento se emplea exclusivamente para narrar cómo los discípulos arrancaban espigas en sábado, un acto que desató polémica sobre la observancia sabática. La ley rabínica consideraba esto una forma de cosecha, prohibida en sábado, aunque los discípulos probablemente lo veían como una comida casual permitida. El incidente se convirtió en caso paradigmático para la enseñanza de Jesús de que el sábado fue hecho para el ser humano, y no al revés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5091', 'spa', 'Honrar, estimar o mostrar respeto a una persona; fijar un precio o valor monetario a algo.', 'Honrar, estimar o mostrar respeto a una persona; fijar un precio o valor monetario a algo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5092', 'spa', 'Honor, estima, respeto; también precio o valor monetario en contextos comerciales.', 'Honor, estima, respeto; también precio o valor monetario en contextos comerciales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5093', 'spa', 'El adjetivo τίμιος abarca la distancia entre el valor material y el honor personal. Con mayor frecuencia describe cosas de valor intrínseco o monetari', 'El adjetivo τίμιος abarca la distancia entre el valor material y el honor personal. Con mayor frecuencia describe cosas de valor intrínseco o monetario: piedras preciosas y oro (1 Corintios 3:12, Apocalipsis 18:12), la preciosa sangre de Cristo (1 Pedro 1:19), y las ''preciosas y grandísimas promesas'' de Dios (2 Pedro 1:4). Pero en dos pasajes notables se desplaza para describir personas tenidas en estima social o moral: Gamaliel como ''honrado por todo el pueblo'' (Hechos 5:34) y el matrimonio como ''honroso entre todos'' (Hebreos 13:4). La evidencia multilingüe sigue con precisión esta bifurcación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5095', 'spa', 'Timoteo — el colaborador más fiel de Pablo y su hijo espiritual, destinatario de dos epístolas pastorales.', 'Timoteo — el colaborador más fiel de Pablo y su hijo espiritual, destinatario de dos epístolas pastorales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5100', 'spa', 'Pronombre indefinido: alguien, alguno, algo; como adjetivo, ''cierto, algún''; en plural, ''algunos, ciertos.''', 'El pronombre indefinido griego τις/τι es una de las palabras más frecuentes y gramaticalmente flexibles del Nuevo Testamento, cumpliendo silenciosamente una función esencial en casi todos los capítulos. Como forma enclítica (átona), contrasta con el interrogativo acentuado τίς (''¿quién?''), y esta distinción de acento conlleva verdadero peso semántico. En su uso sustantivo crea las figuras anónimas que pueblan los Evangelios — ''cierto hombre,'' ''alguien en la multitud,'' ''cierta mujer'' — dando textura narrativa sin necesidad de nombres. Lucas lo emplea especialmente como recurso narrativo, introduciendo personajes de parábolas con ''un hombre tenía...'' (Lucas 15:11; 16:1, 19). La evidencia multilingüe muestra cómo las lenguas manejan la indefinitud de modo diverso: el español distingue ''alguien/algo,'' el alemán ''jemand/etwas,'' y el árabe ''aḥadun/shayʾan.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5101', 'spa', 'Pronombre interrogativo: qué, cuál, quién, a quién, por qué; rara vez indefinido ''alguien, algo.''', 'El pronombre interrogativo griego τίς es la palabra de pregunta por excelencia del Nuevo Testamento, abarcando personas (''¿quién?''), cosas (''¿qué?'') y razones (''¿por qué?''). Su versatilidad proviene del sistema de casos del griego: una misma raíz cambia de sentido según las preposiciones y el contexto gramatical. Cuando Jesús pregunta τί μεριμνᾶτε (''¿por qué os afanáis?'', Mt 6:28), el acusativo neutro funciona con valor causal. El español distingue cuidadosamente ''quién'' de ''qué'' y ''por qué'', revelando tres casillas semánticas que el griego reúne en un solo pronombre flexible. En contadas ocasiones adquiere valor indefinido — ''alguien'' o ''algo'' — difuminando la frontera entre pregunta y afirmación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5103', 'spa', 'Tito -- nombre propio que designa principalmente al colaborador gentil de Pablo y, en una variante textual, a Ticio Justo.', 'Tito -- nombre propio que designa principalmente al colaborador gentil de Pablo y, en una variante textual, a Ticio Justo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5104', 'spa', 'los/las (nominativo plural); formas épicas y poéticas del artículo definido o pronombre demostrativo', 'Estas formas (τοί, ταί) funcionaban como equivalentes épicos y poéticos de las formas áticas estándar del artículo οἱ y αἱ (nominativo plural). Homero las usaba libremente, mientras que rara vez aparecían en la prosa jónica o en la tragedia, aunque eran normales en el dórico y otros dialectos. En algunos dialectos funcionaban como el artículo definido regular, como cuando el griego siracusano decía ''Hierón y los siracusanos'' usando τοί. Estas formas reflejan la antigua diversidad dialectal del griego antes de que el ático se impusiera como estándar literario dominante, recordándonos que el griego bíblico se situaba al final de una larga tradición donde distintas comunidades hablaban variedades reconociblemente diferentes de la lengua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5106', 'spa', 'Por tanto, así pues, en consecuencia; partícula inferencial que introduce una conclusión lógica', 'Esta conjunción señala una consecuencia lógica o introduce una conclusión basada en lo que precede. Ligeramente más enfática que el común οὖν (por tanto), τοίνυν aparece pocas veces en el Nuevo Testamento, aunque era frecuente en el diálogo clásico y el discurso filosófico. Suele introducir una aplicación práctica o una respuesta a un argumento. La partícula combina τοί (marcador enfático) con νῦν (ahora), generando un sentido de «pues bien» o «así pues» que transita de la premisa a la conclusión con cierta fuerza retórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5108', 'spa', 'Tal, de tal clase; referido a personas, cualidades o cosas de un carácter descrito.', 'Pronombre demostrativo que señala la cualidad o el carácter de algo ya descrito o implícito: ''tal persona'', ''de esta clase'', ''tales cosas''. En los Evangelios, Jesús lo emplea para identificar el tipo de persona que pertenece al reino (''de los tales es el reino de Dios'', Mt 19:14; Mc 9:37). Pablo lo usa para caracterizar conductas o personas (Ro 1:32; 2:2). El alemán solch/solches y el español tal/tales reflejan consistentemente este señalamiento cualitativo, dirigiendo la atención no a un individuo específico sino a un tipo o carácter.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5111', 'spa', 'Atreverse, aventurarse con audacia; reunir el valor para una acción ante la que otros retrocederían, o mostrar osadía como disposición interior. Enrai', 'Atreverse, aventurarse con audacia; reunir el valor para una acción ante la que otros retrocederían, o mostrar osadía como disposición interior. Enraizado en el griego antiguo τολμάω, este verbo capta el momento en que la vacilación cede ante la acción. En los Evangelios suele marcar un punto de inflexión: tras la crucifixión, José de Arimatea «se atrevió» a pedir a Pilato el cuerpo de Jesús (Mc 15:43), y los líderes religiosos ya no «se atrevían» a cuestionar a Jesús (Mt 22:46; Lc 20:40). Pablo lo usa para hablar de la audacia apostólica, contrastando la timidez con el valor que la fe exige (2 Cor 11:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5117', 'spa', 'Lugar: ubicación física, región o sitio designado; a veces posición, oportunidad o espacio en sentido figurado.', 'Τόπος es la palabra griega estándar para ''lugar'' tanto en sentido literal como extendido. En los Evangelios designa ubicaciones geográficas concretas: el ''lugar desierto'' donde Jesús alimenta a la multitud (Mt 14:13, 15), el Gólgota, ''el lugar llamado de la Calavera'' (Mt 27:33), y el ''lugar santo'' de la profecía de Daniel (Mt 24:15). Hechos y las Epístolas lo extienden ocasionalmente hacia ''oportunidad'' o ''posición'' (''dad lugar a la ira'', Ro 12:19; ''no deis lugar al diablo'', Ef 4:27). Apocalipsis lo despliega en dimensión cósmica: los lugares del cielo y la tierra (Ap 6:14; 12:8; 20:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5118', 'spa', 'Tanto, tantos, tan grande; pronombre demostrativo de cantidad, número o grado. Τοσοῦτος es un pronombre demostrativo correlativo que señala enfáticame', 'Tanto, tantos, tan grande; pronombre demostrativo de cantidad, número o grado. Τοσοῦτος es un pronombre demostrativo correlativo que señala enfáticamente la cantidad o el grado: «tantos», «tanto», «tan grande». A menudo lleva una nota de asombro o reproche: ¿cómo es posible que tantas señales no produjeran fe (Jn 12:37)? ¿Tanto tiempo llevas conmigo y aún no me conoces (Jn 14:9)? El autor de Hebreos lo usa en comparaciones: Cristo es «tanto más» superior a los ángeles (Heb 1:4), y la gran nube de testigos es «tan grande» (Heb 12:1). Su colorido emocional lo convierte en algo más que un mero numeral; registra asombro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5119', 'spa', 'Entonces; en aquel momento, indicando secuencia temporal o consecuencia lógica en la narración.', 'Τότε es el conector narrativo emblemático de Mateo, donde aparece con una frecuencia muy superior a la de cualquier otro libro del Nuevo Testamento. Marca el siguiente paso en una cadena de acontecimientos: ''entonces Jesús fue llevado al desierto'' (Mt 4:1), ''entonces Herodes llamó en secreto a los magos'' (Mt 2:7). Aunque a veces es puramente temporal, con frecuencia conlleva un sentido de flujo consecuencial: porque ocurrió esto, entonces siguió aquello. Su traducción uniforme en las distintas lenguas — ''entonces'' (español), ''alors'' (francés), ''dann'' (alemán) — confirma una función adverbial estable y sin ambigüedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5120', 'spa', 'el, la, lo; artículo definido o pronombre demostrativo/relativo con compleja historia dialectal', 'Esta entrada cubre ὁ, ἡ, τό en sus múltiples funciones superpuestas a lo largo de los dialectos griegos y períodos históricos. En la prosa ática servía principalmente como artículo definido (''el, la, lo''), un desarrollo relativamente tardío en griego. En Homero aún podía funcionar como demostrativo (''este, aquel'') o incluso como pronombre relativo (''quien, el cual''). Las formas muestran una desconcertante variación dialectal: diferentes dialectos conservaron distintas formas casuales, particularmente en el dual y en los casos menos frecuentes. Los gramáticos modernos debaten si las formas nominativas eran originalmente oxítonas o átonas. Esta palabra representa uno de los elementos más fundamentales de la sintaxis griega, evolucionando desde sus orígenes demostrativos hasta convertirse en artículo gramatical, conservando vestigios de funciones más antiguas en la poesía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5121', 'spa', 'Al contrario, por el contrario; marcador adversativo fuerte que indica oposición a lo esperado', 'Este adverbio introduce un contraste marcado, señalando algo opuesto a lo que se esperaría o a lo recién mencionado. Es una forma contracta (τοὐναντίον, de τὸ ἐναντίον) que intensifica la inversión. Sus tres usos neotestamentarios aparecen en Pablo y Pedro, introduciendo giros sorprendentes: perdonar en lugar de castigar, aceptar en vez de rechazar, bendecir en lugar de maldecir. La expresión señala que los caminos de Dios frecuentemente van en sentido contrario al instinto humano y a las convenciones sociales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5123', 'spa', 'esto es, es decir; fórmula explicativa que introduce una aclaración o reformulación', 'Se trata de una forma contracta de τοῦτ᾽ ἔστι, literalmente ''esto es'', usada como fórmula explicativa o aclaratoria con el sentido de ''es decir'' o ''en otras palabras''. Funcionaba como las aclaraciones parentéticas modernas, permitiendo a los autores reformular algo en otros términos o aportar mayor especificidad. Los autores del Nuevo Testamento la empleaban al definir términos, explicar conceptos o asegurarse de que los lectores comprendieran la importancia de lo recién enunciado. Su contracción en una sola palabra la convirtió en un marcador discursivo estándar que introducía material explicativo sin interrumpir el flujo narrativo o argumentativo, tendiendo un puente entre términos técnicos o extranjeros y la comprensión de los lectores griegos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5124', 'spa', 'esto (neutro singular); formas nominativa y acusativa del demostrativo neutro singular ''esto''', 'Se trata de τοῦτο, la forma de nominativo y acusativo singular neutro del pronombre demostrativo οὗτος, que significa ''esto'' o ''esta cosa''. En griego, donde abundaban los conceptos abstractos y los sustantivos neutros, esta forma se usaba constantemente. Podía referirse a declaraciones (''este dicho''), eventos (''esto que sucedió'') o ideas abstractas (''esta verdad''). La forma neutra era especialmente importante para aludir a cláusulas o proposiciones enteras: ''esto que se acaba de decir''. Los autores bíblicos la empleaban para resaltar declaraciones significativas, señalar signos milagrosos o indicar propósitos divinos. Su función acusativa la hacía esencial para expresiones como ''hago esto'' o ''viendo esto'' en la sintaxis griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5125', 'spa', 'estos/estas cosas (dativo plural neutro); forma dativa plural de ''estas cosas'' o ''por estos medios''', 'Esta es la forma τούτοις, dativo plural neutro del demostrativo, que significa ''a/para estas cosas'', ''por estos medios'' o ''en estos asuntos''. El plural neutro era fundamental en griego para referirse a conjuntos abstractos, múltiples hechos o categorías de cosas. El caso dativo indicaba objetos indirectos, medios o ubicación (''en estas cosas''). Los escritores bíblicos lo empleaban en expresiones como ''por estos medios'', ''respecto a estos asuntos'' o ''en estas circunstancias''. La forma permitía hacer referencia compacta a múltiples elementos o situaciones complejas sin repetición, y era especialmente frecuente en el discurso teológico y ético donde se necesitaba aludir a conjuntos de principios, enseñanzas o condiciones previamente mencionadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5126', 'spa', 'de este, a este (singular oblicuo masculino/neutro); formas de genitivo y dativo de ''este''', 'Abarca las formas τούτου (genitivo singular masculino/neutro, ''de este'') y τούτῳ (dativo singular masculino/neutro, ''a/para este''). El genitivo marcaba posesión (''de este hombre''), origen (''de esto'') o relación, mientras que el dativo indicaba objeto indirecto, medio o ubicación (''en esto''). Como el griego solo distinguía masculino de neutro en nominativo y acusativo singular, estas formas oblicuas servían para ambos géneros. Los textos bíblicos las usaban constantemente para mantener la referencia a sustantivos masculinos o neutros previamente mencionados —personas, conceptos, tiempos o lugares— a lo largo de estructuras oracionales complejas sin repetición tediosa. Estas formas eran el pegamento sintáctico que cohesionaba el discurso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5127', 'spa', 'de esto, por esto; genitivo singular neutro del demostrativo, indicando origen o medio', 'Esta es la forma τούτου en su función específica de genitivo singular neutro, que significa ''de esta cosa'' o ''a partir de esto''. Aunque la forma es idéntica al genitivo masculino, el contexto determinaba si se refería a personas masculinas o a conceptos neutros. En uso neutro aparecía frecuentemente en expresiones que indicaban origen (''de esto''), causa (''a causa de esto'') o relaciones partitivas (''parte de esto''). Los escritores bíblicos la empleaban en afirmaciones teológicas sobre la fuente de la gracia, la razón del juicio o la naturaleza de las realidades espirituales. El genitivo neutro resultaba particularmente importante para el razonamiento abstracto y las declaraciones explicativas que caracterizaban las epístolas del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5128', 'spa', 'estas cosas (acusativo plural neutro); forma acusativa plural que señala múltiples cosas o hechos', 'Esta es la forma ταῦτα, acusativo plural neutro que significa ''estas cosas'' como objeto directo. Era una de las formas más frecuentes en la prosa griega y los textos bíblicos, permitiendo a los escritores referirse a múltiples elementos, enseñanzas, eventos o conceptos abstractos. En el discurso, expresiones como ''oír estas cosas'', ''ver estas cosas'' o ''hacer estas cosas'' estructuraban constantemente la narrativa y la argumentación. El plural neutro captaba conjuntos de hechos, enseñanzas o circunstancias sin especificar género ni contar elementos individuales. Los dichos de Jesús frecuentemente concluían con ''el que tiene oídos para oír estas cosas'', mientras que las cartas apostólicas exhortaban a los lectores a ''recordar estas cosas'' o ''practicar estas cosas''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5129', 'spa', 'por esto, de esta manera; dativo singular neutro que indica medio, manera o ubicación', 'Esta es la forma τούτῳ en su función de dativo singular neutro, que significa ''por esto'', ''de esta manera'' o ''por esta razón''. Aunque idéntica en forma al dativo masculino, su uso neutro indicaba medio, manera o causa en lugar de personas. Expresiones como ''en esto conocemos'' o ''de esta manera se cumplió'' estructuraban la argumentación teológica bíblica. El dativo de medio era particularmente importante para explicar cómo se cumplían los propósitos divinos o cómo podían reconocerse las realidades espirituales. Los escritores bíblicos lo utilizaban para conectar principios abstractos con resultados concretos, mostrando el mecanismo o indicador mediante el cual las verdades podían comprenderse o verificarse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5130', 'spa', 'estos, estas (plural demostrativo); formas plurales oblicuas que señalan personas o cosas previamente mencionadas', 'Este lema abarca las formas plurales oblicuas del demostrativo: τούτων (genitivo, ''de estos/estas''), τούτοις (dativo, ''a/para estos/estas'') y τούτους/ταύτας (acusativo, ''a estos/estas'' como objeto directo). Estas formas servían para los tres géneros en los casos oblicuos del plural, aunque el acusativo distinguía masculino (τούτους) de femenino (ταύτας). Permitían referirse a grupos de personas, conjuntos de cosas o colecciones de conceptos sin necesidad de repetición. En las narraciones bíblicas, estas formas rastreaban discípulos, autoridades, enseñanzas o eventos a lo largo de pasajes complejos. En la instrucción apostólica, expresiones como ''a estos'' o ''de estas cosas'' conectaban mandamientos éticos con grupos específicos de creyentes, mientras que ''estas cosas'' reunían verdades teológicas en unidades manejables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5131', 'spa', 'Macho cabrío; cabra macho usada exclusivamente en el NT para animales sacrificiales en contextos cultuales.', 'Se refiere específicamente a un macho cabrío, distinguido en griego de la αἴξ genérica (cabra hembra). Las cuatro apariciones neotestamentarias se hallan en Hebreos, donde el autor contrasta la sangre de machos cabríos y toros con el sacrificio único y definitivo de Cristo. El término evoca los animales prescritos para los rituales de expiación levítica, y la fuerza retórica de Heb 10:4 —«es imposible que la sangre de toros y machos cabríos quite los pecados»— depende de reconocer que se trata de las ofrendas más solemnes disponibles bajo la Antigua Alianza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5132', 'spa', 'Mesa -- principalmente para comer y la convivencia, pero también mostrador de cambista o banco.', 'Mesa -- principalmente para comer y la convivencia, pero también mostrador de cambista o banco.');